# -*- coding: utf-8 -*-
"""Physics II (PHY1.002) - Optics: chapter 8 Nature and propagation of light, 9 Geometric optics, 10 Interference, 11 Diffraction.
Sources: tutorial chapters 33-36 (Young and Freedman problems), the optics lectures (2024-25 and 2025-26) and the optics tutoring material."""
import math
import numpy as np
from phys_common import *
from phys_verify import refraction_by_fermat, lens_image, mirror_image, refraction_surface_image, slit_intensity, two_slit_intensity
import figs

T33 = "Tutorial chapter 33"
T34 = "Tutorial chapter 34"
T35 = "Tutorial chapter 35"
T36 = "Tutorial chapter 36"
LEC8 = "Optics lecture: the nature and propagation of light"
LEC9 = "Optics lecture: geometric optics"
LEC10 = "Optics lecture: interference"
LEC11 = "Optics lecture: diffraction"
GEN = lambda s: "Generated, same style as: " + s
C = C_LIGHT
sin, cos, tan, asin, atan = (lambda d: math.sin(math.radians(d))), (lambda d: math.cos(math.radians(d))), (lambda d: math.tan(math.radians(d))), (lambda x: math.degrees(math.asin(x))), (lambda x: math.degrees(math.atan(x)))
NM = 1e-9

# =============================================================================================== chapter 8
def ch8(B):
    c = "c8"
    # ---------------------------------------------------------------- 33.1 two mirrors at right angles
    th = atan(11.5 / 14.0)
    mcq_num(B, c, "Reflection", 3, "Two plane mirrors meet at right angles. A laser beam strikes the first at a point $11.5\\,\\mathrm{cm}$ from the intersection and, after reflecting, hits the midpoint of the second mirror ($28.0\\,\\mathrm{cm}$ long). What is the angle of incidence at the first mirror?", th, [atan(14.0 / 11.5), 45.0, atan(11.5 / 28.0), 90.0 - th * 0.5], "deg", ex("The reflected ray goes from $(11.5,\\,0)$ on the first mirror to $(0,\\,14.0)$ on the second: it makes an angle $\\theta$ with the NORMAL of the first mirror where $\\tan\\theta=\\dfrac{11.5}{14.0}$.", "$\\theta=\\arctan0.821=39.4^\\circ$. By the law of reflection this is also the angle of incidence."), T33 + ", 33.1", sig=3)
    # ---------------------------------------------------------------- 33.2 light in the vitreous humor
    n = 1.34
    lam_v, lam_r = 380.0, 750.0
    mcq_num(B, c, "Speed, wavelength and refractive index", 2, "Visible light of wavelength $380\\,\\mathrm{nm}$ (violet, measured in air) enters the vitreous humor of the eye, $n=1.34$. What is its wavelength inside?", lam_v / n, [lam_v * n, lam_v, lam_v / n ** 2, lam_r / n], "nm", ex("The frequency stays the same; the wavelength shrinks by $n$: $\\lambda=\\dfrac{\\lambda_0}{n}=\\dfrac{380}{1.34}=284\\,\\mathrm{nm}$ (the red end, $750\\,\\mathrm{nm}$, becomes $560\\,\\mathrm{nm}$)."), T33 + ", 33.2(a)", sig=3)
    f_r = C / (lam_r * NM)
    mcq_num(B, c, "Speed, wavelength and refractive index", 2, "What is the frequency of red light of wavelength $750\\,\\mathrm{nm}$ (in air), and does it change inside the humor ($n=1.34$)?", f_r, [f_r * n, f_r / n, C / (lam_r * NM * n) * n ** 2, f_r * 2], "Hz", ex("$f=\\dfrac{c}{\\lambda_0}=\\dfrac{3.00\\times10^8}{750\\times10^{-9}}=4.00\\times10^{14}\\,\\mathrm{Hz}$ and it is the SAME inside the humor: the frequency is set by the source; speed and wavelength both change."), T33 + ", 33.2(b)", sig=3)
    mcq_num(B, c, "Speed, wavelength and refractive index", 1, "What is the speed of light inside the vitreous humor ($n=1.34$)?", C / n, [C * n, C / n ** 2, C, C / (n - 1)], "m/s", ex("$v=\\dfrac cn=\\dfrac{3.00\\times10^8}{1.34}=2.24\\times10^{8}\\,\\mathrm{m/s}$."), T33 + ", 33.2(c)", sig=3)
    # ---------------------------------------------------------------- 33.7 reflection / refraction at glass
    ang_surf, ng = 47.5, 1.66
    inc = 90.0 - ang_surf
    refr = asin(sin(inc) / ng); ref_f = refraction_by_fermat(1.0, ng, inc)
    check(refr, ref_f, 1e-5, "Snell's law against Fermat's principle")
    mcq_num(B, c, "Snell's law", 2, "A parallel beam of light in air makes an angle of $47.5^\\circ$ with the SURFACE of a glass plate of refractive index $1.66$. What is the angle between the refracted beam and the surface?", 90.0 - refr, [refr, 47.5, asin(sin(ang_surf) / ng), 90.0 - asin(sin(inc) * ng * 0.5)], "deg", ex("Angles in Snell's law are measured from the NORMAL: $\\theta_1=90^\\circ-47.5^\\circ=42.5^\\circ$.", "$\\sin\\theta_2=\\dfrac{\\sin42.5^\\circ}{1.66}=0.407\\Rightarrow\\theta_2=24.0^\\circ$ from the normal, i.e. $66.0^\\circ$ from the surface. (Fermat's principle - minimising the travel time numerically - gives the same bend.)"), T33 + ", 33.7(b)", sig=3)
    mcq_num(B, c, "Reflection", 1, "A beam in air makes an angle of $47.5^\\circ$ with the surface of a glass plate. What is the angle between the REFLECTED beam and the surface?", 47.5, [42.5, 95.0, 24.0, 66.0], "deg", ex("Law of reflection: the angle of reflection equals the angle of incidence, whether both are measured from the normal ($42.5^\\circ$) or both from the surface ($47.5^\\circ$)."), T33 + ", 33.7(a)", sig=3)
    # ---------------------------------------------------------------- 33.17 critical angle
    thc = 42.5
    n_l = 1 / sin(thc)
    a1 = asin(n_l * sin(35.0)); a2 = asin(sin(35.0) / n_l)
    check(a1, refraction_by_fermat(n_l, 1.0, 35.0), 1e-5); check(a2, refraction_by_fermat(1.0, n_l, 35.0), 1e-5)
    mcq_num(B, c, "Total internal reflection", 2, "The critical angle for total internal reflection at a liquid-air interface is $42.5^\\circ$. What is the refractive index of the liquid?", n_l, [sin(thc), 1 / cos(thc), 1 / tan(thc), n_l / 2], "", ex("At the critical angle the refracted ray grazes the surface ($90^\\circ$): $n\\sin\\theta_c=1\\Rightarrow n=\\dfrac{1}{\\sin42.5^\\circ}=1.48$."), T33 + ", 33.17", sig=3)
    mcq_num(B, c, "Snell's law", 2, "The liquid ($n=1.48$, critical angle $42.5^\\circ$) lies below air. A ray in the liquid reaches the surface at $35.0^\\circ$. At what angle to the normal does it emerge into the air?", a1, [asin(sin(35.0) / n_l), 35.0, 90.0 - a1, 2 * 35.0], "deg", ex("$n_{liq}\\sin35.0^\\circ=\\sin\\theta\\Rightarrow\\sin\\theta=1.48\\times0.574=0.849\\Rightarrow\\theta=58.1^\\circ$: the ray bends AWAY from the normal going into the less dense medium (and $35.0^\\circ<42.5^\\circ$, so it does emerge)."), T33 + ", 33.17(a)", sig=3)
    mcq_num(B, c, "Snell's law", 2, "For the same liquid ($n=1.48$), a ray in AIR hits the surface at $35.0^\\circ$ to the normal. What is the angle of refraction in the liquid?", a2, [a1, 35.0, 35.0 / n_l, 90.0 - a2], "deg", ex("$\\sin\\theta_2=\\dfrac{\\sin35.0^\\circ}{1.48}=0.388\\Rightarrow\\theta_2=22.8^\\circ$: towards the normal when entering the denser medium."), T33 + ", 33.17(b)", sig=3)
    # ---------------------------------------------------------------- 33.25 dispersion in glass
    nr, nv = sin(57.0) / sin(38.1), sin(57.0) / sin(36.7)
    mcq_num(B, c, "Speed, wavelength and refractive index", 2, "A beam hits glass at $57.0^\\circ$ to the normal in air. Red light refracts at $38.1^\\circ$ and violet at $36.7^\\circ$. What is the refractive index of the glass for red light?", nr, [nv, sin(38.1) / sin(57.0), 57.0 / 38.1, nr * 0.5 + 0.5], "", ex("Snell: $n_r=\\dfrac{\\sin57.0^\\circ}{\\sin38.1^\\circ}=\\dfrac{0.8387}{0.6173}=1.36$ (violet: $\\dfrac{0.8387}{0.5976}=1.40$ - violet bends more)."), T33 + ", 33.25(a)", sig=3)
    mcq_num(B, c, "Speed, wavelength and refractive index", 2, "In that glass the index is $1.36$ for red and $1.40$ for violet. What is the speed of VIOLET light in the glass?", C / nv, [C / nr, C * nv, C / nv ** 2, C / (nv - 1)], "m/s", ex("$v=\\dfrac cn=\\dfrac{3.00\\times10^8}{1.40}=2.14\\times10^{8}\\,\\mathrm{m/s}$, slower than red ($2.21\\times10^8\\,\\mathrm{m/s}$): the glass disperses white light."), T33 + ", 33.25(b)", sig=3)
    # ---------------------------------------------------------------- 33.27 polarizers
    mcq_num(B, c, "Polarization", 2, "Unpolarised light of intensity $I_0$ passes through two polarising filters. The first axis is $60.0^\\circ$ from the vertical; the second axis is horizontal. What fraction of $I_0$ emerges?", 0.5 * cos(30.0) ** 2, [0.5 * cos(60.0) ** 2, 0.5, cos(30.0) ** 2, 0.25 * cos(30.0)], "", ex("The first filter halves the intensity: $I_1=\\tfrac12I_0$. The angle between the axes is $90^\\circ-60^\\circ=30^\\circ$.", "Malus' law: $I_2=I_1\\cos^2\\theta=\\tfrac12I_0\\cos^230^\\circ=0.375\\,I_0$."), T33 + ", 33.27", sig=3)
    # ---------------------------------------------------------------- 33.31 Brewster
    thB = 54.5
    nB = tan(thB)
    mcq_num(B, c, "Polarization", 2, "Unpolarised light in air is incident at $54.5^\\circ$ on a plane glass surface and the reflected beam is completely linearly polarised. What is the refractive index of the glass?", nB, [sin(thB), 1 / tan(thB), cos(thB), 1 / sin(thB)], "", ex("Brewster's law: $\\tan\\theta_B=\\dfrac{n_2}{n_1}\\Rightarrow n=\\tan54.5^\\circ=1.40$."), T33 + ", 33.31(a)", sig=3)
    mcq_num(B, c, "Polarization", 2, "For that glass ($n=1.40$) at the Brewster angle $54.5^\\circ$, what is the angle of refraction of the transmitted beam?", 90.0 - thB, [thB, asin(sin(thB) / nB * 0.5), 90.0 - thB / 2, 45.0], "deg", ex("At the Brewster angle the reflected and refracted rays are perpendicular, so $\\theta_r=90^\\circ-\\theta_B=35.5^\\circ$ (check with Snell: $\\sin35.5^\\circ=\\dfrac{\\sin54.5^\\circ}{1.40}$)."), T33 + ", 33.31(b)", sig=3)
    for ng_, name in [(1.50, "crown glass"), (1.33, "water")]:
        mcq_num(B, c, "Polarization", 1, "What is Brewster's angle for light in air reflecting from %s ($n=%s$)?" % (name, sci(ng_)), atan(ng_), [asin(1 / ng_), asin(ng_ / 2), atan(1 / ng_), 90.0 - atan(ng_) * 0.5], "deg", ex("$\\tan\\theta_B=n=%s\\Rightarrow\\theta_B=%s^\\circ$." % (sci(ng_), sci(atan(ng_)))), GEN(T33 + ", 33.31"), "gen", sig=3)
    for ang in (30.0, 60.0, 20.0):
        mcq_num(B, c, "Polarization", 1, "Linearly polarised light of intensity $I_0$ passes through a polariser whose axis makes %s° with the plane of polarisation. What is the transmitted intensity (in units of $I_0$)?" % sci(ang), cos(ang) ** 2, [cos(ang), sin(ang) ** 2, 0.5, cos(ang) ** 2 / 2], "", ex("Malus' law: $I=I_0\\cos^2\\theta=\\cos^2%s^\\circ=%s\\,I_0$ (the amplitude is multiplied by $\\cos\\theta$, the intensity by $\\cos^2\\theta$)." % (sci(ang), sci(cos(ang) ** 2))), GEN(T33 + ", 33.27"), "gen", sig=3)
    # ---------------------------------------------------------------- 33.37 ultrasound
    v_air, v_mus = 344.0, 1480.0
    s_ang = asin(v_mus / v_air * sin(9.73))
    mcq_num(B, c, "Snell's law", 3, "Ultrasound travels at $344\\,\\mathrm{m/s}$ in the lungs and $1480\\,\\mathrm{m/s}$ in muscle. A beam leaves the lungs at $9.73^\\circ$ from the normal to the heart wall. At what angle from the normal does it enter the heart? (Snell's law applies with $n=v_{air}/v$.)", s_ang, [asin(v_air / v_mus * sin(9.73)), 9.73, 9.73 * v_mus / v_air, 90.0 - s_ang], "deg", ex("Define $n_{lung}=\\dfrac{344}{344}=1$ and $n_{muscle}=\\dfrac{344}{1480}=0.232$. Snell: $\\sin\\theta_2=\\dfrac{n_1}{n_2}\\sin\\theta_1=\\dfrac{1480}{344}\\sin9.73^\\circ=0.727$.", "$\\theta_2=46.6^\\circ$: the sound bends AWAY from the normal into the faster medium."), T33 + ", 33.37(a)", sig=3)
    mcq_num(B, c, "Total internal reflection", 3, "For sound waves going from air ($344\\,\\mathrm{m/s}$) into muscle ($1480\\,\\mathrm{m/s}$), what is the critical angle?", asin(v_air / v_mus), [asin(v_mus / v_air * 0.2), 90.0 - asin(v_air / v_mus), atan(v_air / v_mus), asin(v_air / v_mus) * 2], "deg", ex("Total reflection occurs when the transmitted ray would exceed $90^\\circ$: $\\sin\\theta_c=\\dfrac{v_{air}}{v_{muscle}}=\\dfrac{344}{1480}=0.232\\Rightarrow\\theta_c=13.4^\\circ$ (waves entering the faster medium)."), T33 + ", 33.37(b)", sig=3)
    # ---------------------------------------------------------------- 33.41 oil on glass
    n_g, th_g = 1.52, 57.2
    n_oil = n_g * sin(th_g)
    mcq_num(B, c, "Total internal reflection", 3, "A ray in a glass block ($n=1.52$) reaches the top surface at $57.2^\\circ$ to the normal. When a layer of oil is placed on the glass the ray is totally reflected. What is the maximum possible refractive index of the oil?", n_oil, [n_g, n_g / sin(th_g), n_g * cos(th_g), 1.0], "", ex("Total reflection at the glass-oil interface needs the incidence angle $\\ge$ the critical angle: $n_g\\sin57.2^\\circ\\ge n_{oil}$.", "$n_{oil,\\max}=1.52\\sin57.2^\\circ=1.28$ (a denser oil, $n>1.28$, would let the ray through)."), T33 + ", 33.41", sig=3)
    # ---------------------------------------------------------------- critical angles and wavelength in a medium
    for nn, name in [(1.52, "glass"), (1.33, "water"), (2.42, "diamond")]:
        tc = asin(1 / nn)
        mcq_num(B, c, "Total internal reflection", 1, "What is the critical angle for light going from %s ($n=%s$) into air?" % (name, sci(nn)), tc, [asin(nn / 2.5), atan(1 / nn), 90.0 - tc, atan(nn)], "deg", ex("$\\sin\\theta_c=\\dfrac{1}{n}=\\dfrac1{%s}\\Rightarrow\\theta_c=%s^\\circ$ (the larger $n$, the smaller $\\theta_c$)." % (sci(nn), sci(tc))), GEN(T33 + ", 33.17"), "gen", sig=3)
    mcq_num(B, c, "Snell's law", 1, "A ray in air hits a water surface ($n=1.33$) at $40^\\circ$ to the normal. At what angle to the normal does it travel in the water?", asin(sin(40.0) / 1.33), [asin(sin(40.0) * 1.33), 40.0 / 1.33, 40.0, 90.0 - asin(sin(40.0) / 1.33)], "deg", ex("$n_1\\sin\\theta_1=n_2\\sin\\theta_2\\Rightarrow\\sin\\theta_2=\\dfrac{\\sin40^\\circ}{1.33}=0.483\\Rightarrow\\theta_2=28.9^\\circ$."), GEN(T33 + ", 33.7"), "gen", sig=3)
    mcq_num(B, c, "Speed, wavelength and refractive index", 1, "Green light of wavelength $550\\,\\mathrm{nm}$ in air enters glass of refractive index $1.5$. What is its wavelength in the glass?", 550.0 / 1.5, [550.0 * 1.5, 550.0, 550.0 / 1.5 ** 2, 550.0 / 0.5], "nm", ex("$\\lambda=\\dfrac{\\lambda_0}{n}=\\dfrac{550}{1.5}=367\\,\\mathrm{nm}$; the colour (frequency) does not change."), GEN(T33 + ", 33.2"), "gen", sig=3)
    # ---------------------------------------------------------------- scattering, electromagnetic waves
    mcq_num(B, c, "Light as an electromagnetic wave", 2, "Rayleigh scattering is proportional to $1/\\lambda^4$. How many times more strongly is violet light ($400\\,\\mathrm{nm}$) scattered than green light ($550\\,\\mathrm{nm}$)?", (550.0 / 400.0) ** 4, [(550.0 / 400.0) ** 2, 550.0 / 400.0, (550.0 / 400.0) ** 3, (400.0 / 550.0) ** 4], "", ex("$\\dfrac{I_v}{I_g}=\\left(\\dfrac{\\lambda_g}{\\lambda_v}\\right)^4=\\left(\\dfrac{550}{400}\\right)^4=3.6$: short wavelengths scatter more, hence the blue sky (and red sunsets)."), GEN(T33 + ", 33.35"), "gen", sig=2)
    f_fm = 88.9e6
    mcq_num(B, c, "Light as an electromagnetic wave", 1, "A radio station broadcasts at $88.9\\,\\mathrm{MHz}$. What is the wavelength of its radio waves?", C / f_fm, [C * f_fm, f_fm / C, C / (2 * math.pi * f_fm), C / f_fm * 100], "m", ex("$\\lambda=\\dfrac cf=\\dfrac{3.00\\times10^8}{88.9\\times10^6}=3.37\\,\\mathrm{m}$."), GEN(T36 + ", 36.15"), "gen", sig=3)
    Em = 100.0
    I = 0.5 * EPS0 * C * Em ** 2
    mcq_num(B, c, "Light as an electromagnetic wave", 3, "A plane electromagnetic wave has an electric-field amplitude of $100\\,\\mathrm{V/m}$. What is its intensity?", I, [EPS0 * C * Em ** 2, I / 2, I * 4, I / 4], "W/m^2", ex("$I=\\tfrac12\\varepsilon_0cE_{\\max}^2=\\tfrac12(8.85\\times10^{-12})(3.00\\times10^8)(100)^2=13\\,\\mathrm{W/m^2}$ (the average of $\\varepsilon_0cE^2$ over a cycle gives the factor $\\tfrac12$)."), LEC8 + " (electromagnetic waves)", "gen", sig=2)
    mcq_pick(B, c, "Light as an electromagnetic wave", 1, "When light passes from air into glass, which quantity does NOT change?", ["frequency", "wavelength", "speed", "direction in general"], 0, ex("The frequency is fixed by the source. $v=c/n$ decreases and $\\lambda=\\lambda_0/n$ shrinks; the direction changes unless the incidence is normal."), LEC8 + " (refraction)", "concept")
    mcq_pick(B, c, "Reflection", 1, "A plane mirror is turned through an angle $\\alpha$ about an axis in its surface while the incident ray stays fixed. The reflected ray turns through", ["$2\\alpha$", "$\\alpha$", "$\\alpha/2$", "$90^\\circ-\\alpha$"], 0, ex("The normal turns by $\\alpha$, so the angle of incidence changes by $\\alpha$, and the angle between incident and reflected rays changes by $2\\alpha$."), LEC8 + " (reflection)", "concept")
    mcq_pick(B, c, "Total internal reflection", 1, "Total internal reflection can occur when light travels", ["from a medium of higher refractive index to one of lower index, at an angle above the critical angle", "from lower to higher refractive index", "at normal incidence", "only in vacuum"], 0, ex("Only going from a denser to a rarer medium is there a critical angle $\\theta_c=\\arcsin(n_2/n_1)$; this is the principle of optical fibres."), LEC8 + " (total internal reflection)", "concept")
    mcq_pick(B, c, "Polarization", 1, "Which phenomenon shows that light is a TRANSVERSE wave?", ["polarisation", "reflection", "refraction", "diffraction"], 0, ex("Only transverse waves can be polarised: the filter selects one direction of oscillation of $\\vec E$. Reflection, refraction and diffraction occur for longitudinal waves (sound) too."), LEC8 + " (polarization)", "concept")
    mcq_pick(B, c, "Light as an electromagnetic wave", 1, "In a vacuum, all electromagnetic waves (radio, visible light, X-rays) share the same", ["speed $c=3.00\\times10^8\\,\\mathrm{m/s}$", "frequency", "wavelength", "energy per photon"], 0, ex("$c=f\\lambda$ is the same for all of them; frequency and wavelength vary inversely."), LEC8 + " (electromagnetic waves)", "concept")

# =============================================================================================== chapter 9
def ch9(B):
    c = "c9"
    # ---------------------------------------------------------------- 34.3 plane mirror
    mcq_num(B, c, "Plane and spherical mirrors", 1, "A $9.0\\,\\mathrm{cm}$ pencil is held perpendicular to a plane mirror with the lead tip $12.0\\,\\mathrm{cm}$ from the mirror and the eraser end $21.0\\,\\mathrm{cm}$ from it. What is the length of the image of the pencil?", 9.0, [21.0, 12.0, 18.0, 33.0], "cm", ex("A plane mirror forms an image as far behind it as the object is in front, with $m=+1$: the image is $9.0\\,\\mathrm{cm}$ long, from $12.0$ to $21.0\\,\\mathrm{cm}$ behind the mirror (so the tip's image is the end nearer the mirror)."), T34 + ", 34.3", sig=3)
    # ---------------------------------------------------------------- 34.5 concave mirror
    f, s = 22.0 / 2, 16.5
    sp, m = mirror_image(f, s)
    check(sp, 1 / (1 / f - 1 / s)); check(m, -sp / s)
    mcq_num(B, c, "Plane and spherical mirrors", 2, "An object $0.600\\,\\mathrm{cm}$ tall is $16.5\\,\\mathrm{cm}$ in front of a concave spherical mirror of radius of curvature $22.0\\,\\mathrm{cm}$. Where is the image (distance in front of the mirror)?", sp, [f, 1 / (1 / f + 1 / s), 22.0 * 16.5 / (22.0 + 16.5), s + f], "cm", ex("$f=\\dfrac R2=11.0\\,\\mathrm{cm}$. Mirror equation $\\dfrac1s+\\dfrac1{s'}=\\dfrac1f$: $\\dfrac1{s'}=\\dfrac1{11.0}-\\dfrac1{16.5}=\\dfrac{1}{33.0}\\Rightarrow s'=33.0\\,\\mathrm{cm}$ in front of the mirror (real). An ABCD ray-matrix calculation gives the same position."), T34 + ", 34.5(b)", sig=3)
    mcq_num(B, c, "Plane and spherical mirrors", 2, "For the same concave mirror ($f=11.0\\,\\mathrm{cm}$) and object ($0.600\\,\\mathrm{cm}$ tall, $16.5\\,\\mathrm{cm}$ away), what is the height of the image, and is it erect or inverted? (Give the signed height; negative = inverted.)", m * 0.600, [-m * 0.600, 0.600, 0.600 / 2, m * 0.600 / 2], "cm", ex("$m=-\\dfrac{s'}{s}=-\\dfrac{33.0}{16.5}=-2.00$: INVERTED and twice as large. $h'=mh=-1.20\\,\\mathrm{cm}$. The image is real (in front of the mirror, $s'>0$)."), T34 + ", 34.5(b)", sig=3)
    # ---------------------------------------------------------------- 34.8 convex ornament
    f8, s8 = -3.0 / 2, 18.0
    sp8, m8 = mirror_image(f8, s8)
    mcq_num(B, c, "Plane and spherical mirrors", 3, "A convex mirror has a radius of curvature of $3.00\\,\\mathrm{cm}$. An object is $18.0\\,\\mathrm{cm}$ in front of it. Where is the image? (Negative: behind the mirror.)", sp8, [-sp8, abs(f8), -3.0, 1 / (1 / s8 - 1 / abs(f8))], "cm", ex("A convex mirror has a NEGATIVE focal length: $f=-\\dfrac R2=-1.50\\,\\mathrm{cm}$.", "$\\dfrac1{s'}=\\dfrac1f-\\dfrac1s=-\\dfrac1{1.50}-\\dfrac1{18.0}=-0.722\\Rightarrow s'=-1.38\\,\\mathrm{cm}$: virtual, behind the mirror."), T34 + ", 34.8", sig=3)
    mcq_num(B, c, "Plane and spherical mirrors", 3, "For that convex mirror ($f=-1.50\\,\\mathrm{cm}$) and an object $18.0\\,\\mathrm{cm}$ away, what is the lateral magnification?", m8, [-m8, sp8 / s8, 1.0 / m8, m8 * 2], "", ex("$m=-\\dfrac{s'}{s}=-\\dfrac{-1.385}{18.0}=+0.0769$: erect and much smaller (a convex mirror always gives a diminished, upright, virtual image)."), T34 + ", 34.8", sig=3)
    # ---------------------------------------------------------------- 34.13 dental mirror
    s13, m13 = 1.25, 2.00
    f13 = s13 * m13 / (m13 - 1)
    sp13, mm = mirror_image(f13, s13)
    check(mm, m13, 1e-9)
    mcq_num(B, c, "Plane and spherical mirrors", 3, "A dentist wants an ERECT image with magnification $2.00$ when the mirror is $1.25\\,\\mathrm{cm}$ from a tooth. What focal length is needed (positive for a concave mirror)?", f13, [-f13, s13, f13 * 2, f13 * 4], "cm", ex("Erect and magnified means a virtual image: $s'=-ms=-2.50\\,\\mathrm{cm}$.", "$\\dfrac1f=\\dfrac1s+\\dfrac1{s'}=\\dfrac1{1.25}-\\dfrac1{2.50}=0.40\\Rightarrow f=+2.50\\,\\mathrm{cm}$: a CONCAVE mirror with $R=5.00\\,\\mathrm{cm}$ (the object lies inside the focal length)."), T34 + ", 34.13", sig=3)
    # ---------------------------------------------------------------- 34.19 / 34.21 apparent depth
    mcq_num(B, c, "Refraction at a surface", 1, "A speck of dirt is embedded $3.50\\,\\mathrm{cm}$ below the surface of a sheet of ice ($n=1.309$). What is its apparent depth when viewed from directly above?", 3.50 / 1.309, [3.50 * 1.309, 3.50, 3.50 / 1.309 ** 2, 3.50 * 0.309], "cm", ex("Plane refracting surface, viewed along the normal: $d_{app}=d\\,\\dfrac{n_{air}}{n_{ice}}=\\dfrac{3.50}{1.309}=2.67\\,\\mathrm{cm}$ (objects under water or ice look closer to the surface)."), T34 + ", 34.19", sig=3)
    h_app = 5.20 - 0.80
    h_true = h_app / 1.33
    mcq_num(B, c, "Refraction at a surface", 3, "A swimmer $0.80\\,\\mathrm{m}$ below the surface of a pool ($n=1.33$) sees the diving board directly overhead at an apparent height of $5.20\\,\\mathrm{m}$ ABOVE HER. What is the actual height of the board above the water?", h_true, [h_app, 5.20 / 1.33, h_app * 1.33, 5.20 - 0.80 / 1.33], "m", ex("The image is $5.20\\,\\mathrm{m}$ above the swimmer, i.e. $5.20-0.80=4.40\\,\\mathrm{m}$ above the SURFACE.", "Object in air seen from water: $h_{app}=\\dfrac{n_{water}}{n_{air}}h\\Rightarrow h=\\dfrac{4.40}{1.33}=3.31\\,\\mathrm{m}$ (things above the surface look higher to a swimmer)."), T34 + ", 34.21", sig=3)
    # ---------------------------------------------------------------- 34.26 refraction at a spherical surface
    di, mm = refraction_surface_image(1.0, 1.60, 4.0, 24.0)
    check(di, 1.60 / ((1.60 - 1.0) / 4.0 - 1.0 / 24.0))
    mcq_num(B, c, "Refraction at a surface", 3, "The end of a long glass rod ($n=1.60$) is ground to a convex hemispherical surface of radius $4.00\\,\\mathrm{cm}$. An object is on the axis $24.0\\,\\mathrm{cm}$ in front of the vertex. Where is the image (inside the glass, measured from the vertex)?", di, [24.0, 1 / ((1.60 - 1.0) / 4.0 + 1.0 / 24.0), 1.60 / ((1.60 - 1.0) / 4.0), 40.0], "cm", ex("Refraction at a spherical surface: $\\dfrac{n_a}{s}+\\dfrac{n_b}{s'}=\\dfrac{n_b-n_a}{R}$ with $n_a=1$, $n_b=1.60$, $R=+4.00\\,\\mathrm{cm}$ (centre on the outgoing side).", "$\\dfrac{1}{24.0}+\\dfrac{1.60}{s'}=0.150\\Rightarrow\\dfrac{1.60}{s'}=0.1083\\Rightarrow s'=14.8\\,\\mathrm{cm}$ (real, in the glass). A ray-matrix calculation agrees."), T34 + ", 34.26", sig=3)
    mcq_num(B, c, "Refraction at a surface", 3, "For that rod (object $24.0\\,\\mathrm{cm}$ away, image at $14.8\\,\\mathrm{cm}$ inside the glass), the arrow is $1.50\\,\\mathrm{mm}$ tall. What is the (signed) height of the image?", mm * 1.50, [-mm * 1.50, 1.50, di / 24.0 * 1.50, mm * 1.50 * 1.6], "mm", ex("$m=-\\dfrac{n_as'}{n_bs}=-\\dfrac{(1.00)(14.8)}{(1.60)(24.0)}=-0.385$: inverted, and $h'=-0.385(1.50)=-0.577\\,\\mathrm{mm}$."), T34 + ", 34.26", sig=3)
    # ---------------------------------------------------------------- 34.29 planoconvex lens
    n_l, R_l, s29 = 1.70, 13.0, 22.5
    f29 = R_l / (n_l - 1)
    di29, m29 = lens_image(f29, s29)
    check(di29, 1 / (1 / f29 - 1 / s29))
    mcq_num(B, c, "Thin lenses", 2, "A thin planoconvex lens (flat face on the left, curved face of radius $13.0\\,\\mathrm{cm}$ on the right, $n=1.70$) is made. What is its focal length?", f29, [R_l / n_l, R_l * (n_l - 1), R_l / (n_l + 1), 2 * R_l / (n_l - 1)], "cm", ex("Lensmaker's formula: $\\dfrac1f=(n-1)\\left(\\dfrac1{R_1}-\\dfrac1{R_2}\\right)$ with $R_1=\\infty$ and $R_2=-13.0\\,\\mathrm{cm}$: $\\dfrac1f=0.70\\left(\\dfrac1{13.0}\\right)\\Rightarrow f=18.6\\,\\mathrm{cm}$ (converging)."), T34 + ", 34.29", sig=3)
    mcq_num(B, c, "Thin lenses", 2, "An insect $3.75\\,\\mathrm{mm}$ tall is $22.5\\,\\mathrm{cm}$ to the left of a thin converging lens of focal length $18.6\\,\\mathrm{cm}$. Where is the image (to the right of the lens)?", di29, [f29, 1 / (1 / f29 + 1 / s29), s29 + f29, f29 * s29 / (s29 + f29)], "cm", ex("$\\dfrac1{s'}=\\dfrac1f-\\dfrac1s=\\dfrac1{18.57}-\\dfrac1{22.5}=9.40\\times10^{-3}\\Rightarrow s'=106\\,\\mathrm{cm}$ (real). The magnification is $m=-\\dfrac{s'}{s}=-4.73$, so the image is $17.7\\,\\mathrm{mm}$ tall and inverted."), T34 + ", 34.29(a)", sig=3)
    mcq_num(B, c, "Thin lenses", 2, "For that insect ($3.75\\,\\mathrm{mm}$ tall, $22.5\\,\\mathrm{cm}$ from a lens with $f=18.57\\,\\mathrm{cm}$), what is the signed height of the image in mm?", m29 * 3.75, [-m29 * 3.75, 3.75 * di29 / s29 * 0.5, m29, m29 * 3.75 / 2], "mm", ex("$m=-\\dfrac{s'}{s}=-\\dfrac{106.4}{22.5}=-4.73$, $h'=-4.73(3.75)=-17.7\\,\\mathrm{mm}$: real, inverted, magnified."), T34 + ", 34.29(a)", sig=3)
    mcq_pick(B, c, "Thin lenses", 2, "If the planoconvex lens is turned around (curved face towards the insect), the focal length of the (thin) lens and the image position", ["do not change: $f$ depends only on $n$ and the two radii", "double", "are halved", "change sign"], 0, ex("$\\dfrac1f=(n-1)\\left(\\dfrac1{R_1}-\\dfrac1{R_2}\\right)$ gives the same $f$ for both orientations of a thin lens (reversing swaps $R_1\\to-R_2$ and $R_2\\to-R_1$)."), T34 + ", 34.29(b)", "src")
    # ---------------------------------------------------------------- 34.32 find object from image size
    h_o, h_i, f32 = 3.20, 4.50, 70.0
    mm32 = -h_i / h_o
    s32 = f32 * (1 - 1 / mm32)
    di32, mchk = lens_image(f32, s32)
    check(mchk, mm32, 1e-9)
    mcq_num(B, c, "Thin lenses", 3, "A converging lens of focal length $70.0\\,\\mathrm{cm}$ forms an image $4.50\\,\\mathrm{cm}$ tall, inverted, of a real object $3.20\\,\\mathrm{cm}$ tall. How far is the object from the lens?", s32, [f32 * (1 + mm32), f32 * (1 - mm32), f32, f32 * 4.50 / 3.20], "cm", ex("Inverted real image: $m=-\\dfrac{4.50}{3.20}=-1.406=-\\dfrac{s'}{s}\\Rightarrow s'=1.406\\,s$.", "$\\dfrac1s+\\dfrac1{1.406s}=\\dfrac1{70.0}\\Rightarrow\\dfrac{1.711}{s}=\\dfrac{1}{70.0}\\Rightarrow s=120\\,\\mathrm{cm}$ and $s'=168\\,\\mathrm{cm}$ (real)."), T34 + ", 34.32", sig=3)
    mcq_num(B, c, "Thin lenses", 3, "For that lens ($f=70.0\\,\\mathrm{cm}$, object at $120\\,\\mathrm{cm}$ giving $m=-1.406$), how far from the lens is the image?", di32, [s32, f32, di32 / 2, 1 / (1 / f32 + 1 / s32)], "cm", ex("$s'=-ms=1.406\\times119.8=168\\,\\mathrm{cm}$ on the other side (real); check: $\\dfrac1{119.8}+\\dfrac1{168.4}=\\dfrac1{70.0}$."), T34 + ", 34.32", sig=3)
    # ---------------------------------------------------------------- 34.43 two converging lenses
    f1, f2, s1, hh, sep = 40.0, 60.0, 50.0, 1.20, 300.0
    d1, mm1 = lens_image(f1, s1); s2 = sep - d1; d2, mm2 = lens_image(f2, s2)
    mtot = mm1 * mm2
    mcq_num(B, c, "Thin lenses", 3, "A $1.20\\,\\mathrm{cm}$ tall object is $50.0\\,\\mathrm{cm}$ to the left of a converging lens ($f=40.0\\,\\mathrm{cm}$). A second converging lens ($f=60.0\\,\\mathrm{cm}$) is $300.0\\,\\mathrm{cm}$ to the right of the first. Where is the image formed by the FIRST lens (to its right)?", d1, [f1, 1 / (1 / f1 + 1 / s1), s1 + f1, 100.0], "cm", ex("$\\dfrac1{s_1'}=\\dfrac1{40.0}-\\dfrac1{50.0}=\\dfrac1{200}\\Rightarrow s_1'=200\\,\\mathrm{cm}$, $m_1=-4.00$: a real, inverted image $4.80\\,\\mathrm{cm}$ tall."), T34 + ", 34.43(a)", sig=3)
    mcq_num(B, c, "Thin lenses", 3, "In the two-lens system above, the first image ($200\\,\\mathrm{cm}$ from lens 1) is the object for lens 2 ($f=60.0\\,\\mathrm{cm}$, $300.0\\,\\mathrm{cm}$ from lens 1). Where is the FINAL image (to the right of lens 2)?", d2, [f2, 1 / (1 / f2 + 1 / s2), 300.0 - d2, s2], "cm", ex("Object distance for lens 2: $s_2=300-200=100\\,\\mathrm{cm}$ (real object).", "$\\dfrac1{s_2'}=\\dfrac1{60.0}-\\dfrac1{100}\\Rightarrow s_2'=150\\,\\mathrm{cm}$ to the right of lens 2 (checked by multiplying the two ray-transfer matrices)."), T34 + ", 34.43(b)", sig=3)
    mcq_num(B, c, "Thin lenses", 3, "For the same system, what is the signed height of the final image (negative means inverted compared with the object)?", mtot * hh, [mm1 * hh, mm2 * hh, -mtot * hh, (mm1 + mm2) * hh], "cm", ex("$m_1=-4.00$ and $m_2=-\\dfrac{150}{100}=-1.50$. Total magnification $m=m_1m_2=+6.00$.", "Final image height $=6.00(1.20)=7.20\\,\\mathrm{cm}$, ERECT relative to the object (two inversions)."), T34 + ", 34.43(b)", sig=3)
    # ---------------------------------------------------------------- 34.45 diverging then converging
    fa, fb, sa, sepb = -12.0, 12.0, 20.0, 9.00
    da, ma = lens_image(fa, sa); sb = sepb - da; db, mb = lens_image(fb, sb)
    mcq_num(B, c, "Thin lenses", 3, "Two thin lenses of focal length magnitude $12.0\\,\\mathrm{cm}$, the first diverging and the second converging, are $9.00\\,\\mathrm{cm}$ apart. An object $2.50\\,\\mathrm{mm}$ tall is $20.0\\,\\mathrm{cm}$ to the left of the diverging lens. How far from the FIRST lens is the final image?", sepb + db, [db, da, sepb - db, sb + sepb], "cm", ex("Lens 1 ($f=-12.0$): $\\dfrac1{s_1'}=-\\dfrac1{12}-\\dfrac1{20}\\Rightarrow s_1'=-7.50\\,\\mathrm{cm}$ (virtual, on the object side).", "Lens 2: object distance $s_2=9.00+7.50=16.5\\,\\mathrm{cm}$; $\\dfrac1{s_2'}=\\dfrac1{12}-\\dfrac1{16.5}\\Rightarrow s_2'=44.0\\,\\mathrm{cm}$ to the right of lens 2, i.e. $53.0\\,\\mathrm{cm}$ from lens 1. The final image is real."), T34 + ", 34.45(a, b)", sig=3)
    mcq_num(B, c, "Thin lenses", 3, "For that two-lens system (diverging $f=-12.0\\,\\mathrm{cm}$ then converging $f=+12.0\\,\\mathrm{cm}$, $9.00\\,\\mathrm{cm}$ apart, object $2.50\\,\\mathrm{mm}$ tall at $20.0\\,\\mathrm{cm}$), what is the signed height of the final image in mm?", ma * mb * 2.50, [ma * 2.50, mb * 2.50, -ma * mb * 2.50, (ma + mb) * 2.50], "mm", ex("$m_1=-\\dfrac{s_1'}{s_1}=-\\dfrac{-7.50}{20.0}=+0.375$ and $m_2=-\\dfrac{44.0}{16.5}=-2.67$; $m=m_1m_2=-1.00$.", "The final image is $2.50\\,\\mathrm{mm}$ tall and INVERTED (negative height)."), T34 + ", 34.45(c)", sig=3)
    # ---------------------------------------------------------------- 34.50 projector, 34.59 magnifier
    s50, d50 = 15.0, 900.0
    f50 = 1 / (1 / s50 + 1 / d50)
    mcq_num(B, c, "Thin lenses", 2, "A slide projector must put a sharp image of a slide on a screen $9.00\\,\\mathrm{m}$ from the lens when the slide is $15.0\\,\\mathrm{cm}$ from the lens. What focal length is required?", f50, [s50, s50 * d50 / (d50 - s50), s50 + d50, (d50 - s50) / 2], "cm", ex("$\\dfrac1f=\\dfrac1s+\\dfrac1{s'}=\\dfrac1{15.0}+\\dfrac1{900}\\Rightarrow f=14.75\\,\\mathrm{cm}$ (just a little shorter than the slide distance: the slide sits just inside $2f$... just outside $f$)."), T34 + ", 34.50(a)", sig=3)
    mcq_num(B, c, "Thin lenses", 2, "The projector above has the slide $15.0\\,\\mathrm{cm}$ and the screen $9.00\\,\\mathrm{m}$ from the lens. A $24\\,\\mathrm{mm}\\times36\\,\\mathrm{mm}$ slide fills a screen of width", 36.0 * d50 / s50 / 1000, [36.0 * d50 / s50 / 100, 36.0 / (d50 / s50) / 1000, 24.0 * d50 / s50 / 1000, 36.0 * (d50 - s50) / s50 / 1000], "m", ex("$|m|=\\dfrac{s'}{s}=\\dfrac{900}{15.0}=60$: the $36\\,\\mathrm{mm}$ side becomes $2.16\\,\\mathrm{m}$ and the $24\\,\\mathrm{mm}$ side $1.44\\,\\mathrm{m}$ (the image is inverted)."), T34 + ", 34.50(b)", sig=3)
    f59, near = 8.00, 25.0
    s59 = 1 / (1 / f59 + 1 / near)
    mag59 = near / s59
    mcq_num(B, c, "Thin lenses", 2, "A simple magnifier has focal length $8.00\\,\\mathrm{cm}$. How far in front of it must an object be placed so that the image is formed at the observer's near point, $25.0\\,\\mathrm{cm}$ in front of the lens?", s59, [f59, 1 / (1 / f59 - 1 / near), near - f59, f59 * near / (near - f59)], "cm", ex("The image is virtual, on the object's side: $s'=-25.0\\,\\mathrm{cm}$. $\\dfrac1s=\\dfrac1f-\\dfrac1{s'}=\\dfrac1{8.00}+\\dfrac1{25.0}=0.165\\Rightarrow s=6.06\\,\\mathrm{cm}$ (inside the focal length)."), T34 + ", 34.59(a)", sig=3)
    mcq_num(B, c, "Thin lenses", 2, "For that magnifier ($f=8.00\\,\\mathrm{cm}$, image at the near point, object at $6.06\\,\\mathrm{cm}$), a $1.00\\,\\mathrm{mm}$ high object gives an image of what height?", mag59, [1 / mag59, near / f59, mag59 - 1, f59 / near], "mm", ex("$m=-\\dfrac{s'}{s}=\\dfrac{25.0}{6.06}=4.13$ (erect, virtual): the image is $4.13\\,\\mathrm{mm}$ high ($m=1+\\dfrac{25}{f}=4.13$ when the image is at the near point)."), T34 + ", 34.59(b)", sig=3)
    # ---------------------------------------------------------------- generated: thin lens equation
    for f_, s_ in [(10.0, 30.0), (20.0, 15.0), (-15.0, 30.0)]:
        di, mq = lens_image(f_, s_)
        kind = "converging" if f_ > 0 else "diverging"
        mcq_num(B, c, "Thin lenses", 2, "An object is %s cm from a %s lens of focal length %s cm. Where is the image (positive: on the far side, real; negative: same side as the object, virtual)?" % (sci(s_), kind, sci(f_)), di, [-di, f_ * s_ / (f_ + s_) if f_ + s_ != 0 else f_, f_ + s_, s_ - f_], "cm", ex("$\\dfrac1{s'}=\\dfrac1f-\\dfrac1s=\\dfrac1{%s}-\\dfrac1{%s}\\Rightarrow s'=%s\\,\\mathrm{cm}$, so the image is %s and %s (magnification $m=-s'/s=%s$)." % (sci(f_), sci(s_), sci(di), "real" if di > 0 else "virtual", "inverted" if mq < 0 else "erect", sci(mq))), GEN(T34 + ", 34.29-34.45"), "gen", sig=3)
    mcq_num(B, c, "Thin lenses", 1, "A biconvex lens has radii of curvature $R_1=+20.0\\,\\mathrm{cm}$ and $R_2=-20.0\\,\\mathrm{cm}$ and refractive index $1.50$. What is its focal length?", 20.0, [10.0, 40.0, 20.0 / 1.5, 30.0], "cm", ex("$\\dfrac1f=(n-1)\\left(\\dfrac1{R_1}-\\dfrac1{R_2}\\right)=0.50\\left(\\dfrac1{20}+\\dfrac1{20}\\right)=\\dfrac1{20}\\Rightarrow f=20.0\\,\\mathrm{cm}$."), GEN(T34 + ", 34.29-34.31"), "gen", sig=3)
    mcq_num(B, c, "Thin lenses", 1, "A lens has a focal length of $25\\,\\mathrm{cm}$. What is its power in dioptres?", 4.0, [25.0, 0.04, 2.5, 1.0 / 0.025], "D", ex("$P=\\dfrac1f=\\dfrac{1}{0.25\\,\\mathrm{m}}=4.0\\,\\mathrm{D}$ (focal length in metres)."), GEN(T34 + ", 34.59"), "gen", sig=2)
    mcq_num(B, c, "Refraction at a surface", 1, "A fish is $2.0\\,\\mathrm{m}$ below the surface of a pond ($n=1.33$). How deep does it appear to an observer looking straight down?", 2.0 / 1.33, [2.0 * 1.33, 2.0, 2.0 / 1.33 ** 2, 2.0 * 0.33], "m", ex("$d_{app}=\\dfrac{d}{n}=\\dfrac{2.0}{1.33}=1.5\\,\\mathrm{m}$."), GEN(T34 + ", 34.19"), "gen", sig=2)
    mcq_num(B, c, "Plane and spherical mirrors", 1, "A person stands $2.0\\,\\mathrm{m}$ in front of a plane mirror. How far is she from her image?", 4.0, [2.0, 1.0, 8.0, 6.0], "m", ex("The image is $2.0\\,\\mathrm{m}$ behind the mirror, so the distance between her and the image is $2.0+2.0=4.0\\,\\mathrm{m}$."), GEN(T34 + ", 34.3"), "gen", sig=2)
    mcq_pick(B, c, "Thin lenses", 2, "An object is placed INSIDE the focal length of a converging lens. The image is", ["virtual, erect and magnified", "real, inverted and magnified", "real, inverted and reduced", "virtual, erect and reduced"], 0, ex("For $s<f$: $\\dfrac1{s'}=\\dfrac1f-\\dfrac1s<0$, so $s'<0$ (virtual, same side as the object) and $m=-\\dfrac{s'}{s}>1$: the magnifying-glass arrangement."), LEC9 + " (thin lenses)", "concept")
    mcq_pick(B, c, "Plane and spherical mirrors", 1, "A convex mirror always forms an image that is", ["virtual, erect and diminished", "real and inverted", "virtual and magnified", "real and erect"], 0, ex("With $f<0$: $s'=\\dfrac{sf}{s-f}$ is negative with $|s'|<s$, so $m=-s'/s$ is between $0$ and $1$."), LEC9 + " (spherical mirrors)", "concept")
    mcq_pick(B, c, "Thin lenses", 1, "A converging lens has a focal length of $15\\,\\mathrm{cm}$. Parallel rays from a distant object are focused", ["$15\\,\\mathrm{cm}$ behind the lens", "at the lens", "$30\\,\\mathrm{cm}$ behind the lens", "on the object's side"], 0, ex("For $s\\to\\infty$: $\\dfrac1{s'}=\\dfrac1f\\Rightarrow s'=f$: the focal point."), LEC9 + " (thin lenses)", "concept")
    mcq_pick(B, c, "Thin lenses", 2, "In the lens equation $\\frac1s+\\frac1{s'}=\\frac1f$ a NEGATIVE image distance $s'$ means the image is", ["virtual, on the same side of the lens as the object", "real, on the far side", "inverted", "at infinity"], 0, ex("Sign convention: $s'>0$ for a real image on the outgoing side; $s'<0$ for a virtual image on the incoming side."), LEC9 + " (sign conventions)", "concept")


def ch8b(B):
    c = "c8"
    n1, n2 = 1.50, 1.45
    tc = asin(n2 / n1)
    NA = math.sqrt(n1 ** 2 - n2 ** 2)
    mcq_num(B, c, "Total internal reflection", 2, "An optical fibre has a core of refractive index $1.50$ and cladding of index $1.45$. What is the critical angle at the core-cladding boundary?", tc, [asin(n1 / 2.0), atan(n2 / n1), 90.0 - tc, asin(1 / n1)], "deg", ex("Light in the core is totally reflected at the cladding when $\\sin\\theta\\ge\\dfrac{n_2}{n_1}$: $\\theta_c=\\arcsin\\dfrac{1.45}{1.50}=75.2^\\circ$ (measured from the normal to the boundary)."), GEN(T33 + ", 33.17"), "gen", sig=3)
    mcq_num(B, c, "Total internal reflection", 3, "For that fibre (core $1.50$, cladding $1.45$), what is the numerical aperture $\\sqrt{n_1^2-n_2^2}$ that fixes the largest acceptance angle from air?", NA, [n1 - n2, n2 / n1, math.sqrt(n1 * n2), n1 ** 2 - n2 ** 2], "", ex("$\\mathrm{NA}=\\sqrt{1.50^2-1.45^2}=\\sqrt{0.1475}=0.384$, so rays entering within $\\arcsin0.384=22.6^\\circ$ of the axis are guided."), GEN(T33 + ", 33.41"), "gen", sig=3)
    t_g = 1.5 * 0.020 / C
    mcq_num(B, c, "Speed, wavelength and refractive index", 2, "How long does light take to cross a glass slab ($n=1.5$) that is $2.0\\,\\mathrm{cm}$ thick?", t_g, [0.020 / C, 0.020 / (C * 1.5), 1.5 ** 2 * 0.020 / C, 0.020 * C / 1.5], "s", ex("In glass the speed is $\\dfrac cn=2.0\\times10^8\\,\\mathrm{m/s}$, so $t=\\dfrac{nL}{c}=\\dfrac{(1.5)(0.020)}{3.00\\times10^8}=1.0\\times10^{-10}\\,\\mathrm{s}$ ($nL$ is the optical path length)."), GEN(T33 + ", 33.2"), "gen", sig=2)
    f_w = C / (1.33 * 400.0 * NM)
    mcq_num(B, c, "Speed, wavelength and refractive index", 2, "Light has a wavelength of $400\\,\\mathrm{nm}$ INSIDE water ($n=1.33$). What is its frequency?", f_w, [C / (400.0 * NM), C * 1.33 / (400.0 * NM), C / (1.33 * 400.0 * NM) / 1.33, f_w * 2], "Hz", ex("$f=\\dfrac{v}{\\lambda}=\\dfrac{c/n}{\\lambda}=\\dfrac{3.00\\times10^8}{(1.33)(400\\times10^{-9})}=5.6\\times10^{14}\\,\\mathrm{Hz}$ (not $c/\\lambda$: the $400\\,\\mathrm{nm}$ is the wavelength in water)."), GEN(T33 + ", 33.2"), "gen", sig=2)
    mcq_num(B, c, "Polarization", 3, "Unpolarised light of intensity $I_0$ passes through three polarisers with axes at $0^\\circ$, $45^\\circ$ and $90^\\circ$ to the vertical. What fraction of $I_0$ emerges?", 0.5 * cos(45.0) ** 2 * cos(45.0) ** 2, [0.0, 0.25, 0.5 * cos(45.0) ** 2, 0.5], "", ex("First: $\\tfrac12I_0$. Second ($45^\\circ$ between axes): $\\times\\cos^245^\\circ=\\tfrac12$. Third ($45^\\circ$ again): $\\times\\tfrac12$. Total $I_0/8=0.125\\,I_0$. Without the middle polariser the crossed pair would pass nothing."), GEN(T33 + ", 33.27"), "gen", sig=3)
    mcq_num(B, c, "Light as an electromagnetic wave", 2, "A $100\\,\\mathrm{W}$ point source radiates light uniformly in all directions. What is the intensity $2.0\\,\\mathrm{m}$ away?", 100.0 / (4 * math.pi * 2.0 ** 2), [100.0 / (2 * math.pi * 2.0 ** 2), 100.0 / (4 * math.pi * 2.0), 100.0 / 2.0 ** 2, 100.0 / (math.pi * 2.0 ** 2)], "W/m^2", ex("$I=\\dfrac{P}{4\\pi r^2}=\\dfrac{100}{4\\pi(2.0)^2}=2.0\\,\\mathrm{W/m^2}$ (inverse-square law)."), GEN(LEC8 + " (electromagnetic waves)"), "gen", sig=2)
    mcq_num(B, c, "Speed, wavelength and refractive index", 1, "Light travels at $2.0\\times10^{8}\\,\\mathrm{m/s}$ in a transparent material. What is its refractive index?", C / 2.0e8, [2.0e8 / C, C * 2.0e8, C / 2.0e8 - 1, 2.0], "", ex("$n=\\dfrac cv=\\dfrac{3.00\\times10^8}{2.0\\times10^8}=1.5$."), GEN(T33 + ", 33.25"), "gen", sig=2)
    mcq_pick(B, c, "Snell's law", 1, "Light passes from air into glass. In the glass the ray", ["bends towards the normal", "bends away from the normal", "does not bend", "reverses direction"], 0, ex("Entering a medium of higher index the speed decreases and the ray bends TOWARDS the normal ($\\theta_2<\\theta_1$)."), LEC8 + " (refraction)", "concept")
    mcq_pick(B, c, "Light as an electromagnetic wave", 2, "Why is the sky blue and the setting Sun red?", ["short wavelengths are scattered more strongly by air molecules ($\\propto1/\\lambda^4$)", "air absorbs red light", "the atmosphere reflects blue light from the sea", "violet light travels faster"], 0, ex("Rayleigh scattering removes blue from the direct beam (leaving it red at sunset) and sends it in all directions (blue sky)."), LEC8 + " (scattering)", "concept")
    mcq_pick(B, c, "Reflection", 1, "A ray hits a plane mirror at $30^\\circ$ to the NORMAL. The angle between the incident and the reflected rays is", ["$60^\\circ$", "$30^\\circ$", "$120^\\circ$", "$90^\\circ$"], 0, ex("The reflected ray is also $30^\\circ$ from the normal, on the other side: $30^\\circ+30^\\circ=60^\\circ$ between the rays."), LEC8 + " (reflection)", "concept")

def ch9b(B):
    c = "c9"
    f, s = 20.0, 10.0
    di, m = mirror_image(f, s)
    mcq_num(B, c, "Plane and spherical mirrors", 2, "An object is $10.0\\,\\mathrm{cm}$ from a concave mirror of focal length $20.0\\,\\mathrm{cm}$ (inside the focal point). Where is the image (negative: behind the mirror)?", di, [-di, f * s / (f + s), f - s, f], "cm", ex("$\\dfrac1{s'}=\\dfrac1f-\\dfrac1s=\\dfrac1{20}-\\dfrac1{10}=-\\dfrac1{20}\\Rightarrow s'=-20.0\\,\\mathrm{cm}$: a virtual image behind the mirror, with $m=-\\dfrac{s'}{s}=+2.0$ (erect, magnified: a make-up mirror)."), GEN(T34 + ", 34.5"), "gen", sig=3)
    fc, sc = -1.0, 5.0
    dc, mc = mirror_image(fc, sc)
    mcq_num(B, c, "Plane and spherical mirrors", 2, "A convex wing mirror has a focal length of $-1.00\\,\\mathrm{m}$. A car is $5.00\\,\\mathrm{m}$ behind it. What is the magnification of the image?", mc, [-mc, dc / sc, mc * 2, 1.0], "", ex("$\\dfrac1{s'}=\\dfrac1f-\\dfrac1s=-1-0.2\\Rightarrow s'=-0.833\\,\\mathrm{m}$ and $m=-\\dfrac{s'}{s}=+0.167$: the car appears upright but six times smaller (wider field of view)."), GEN(T34 + ", 34.8"), "gen", sig=3)
    f1, f2 = 20.0, 30.0
    fc2 = 1 / (1 / f1 + 1 / f2)
    mcq_num(B, c, "Thin lenses", 2, "Two thin converging lenses of focal lengths $20.0\\,\\mathrm{cm}$ and $30.0\\,\\mathrm{cm}$ are in contact. What is the focal length of the combination?", fc2, [f1 + f2, (f1 + f2) / 2, f1 * f2, f2 - f1], "cm", ex("In contact, the POWERS add: $\\dfrac1f=\\dfrac1{20.0}+\\dfrac1{30.0}=\\dfrac{1}{12.0}\\Rightarrow f=12.0\\,\\mathrm{cm}$ (the powers add: $5.00+3.33=8.33\\,\\mathrm{D}$)."), GEN(T34 + ", 34.43"), "gen", sig=3)
    fcam, sd = 50.0, 2000.0
    dcam, mcam = lens_image(fcam, sd)
    mcq_num(B, c, "Thin lenses", 2, "A camera lens of focal length $50.0\\,\\mathrm{mm}$ is focused on a subject $2.00\\,\\mathrm{m}$ away. How far is the lens from the sensor?", dcam, [fcam, sd, 1 / (1 / fcam + 1 / sd), fcam * sd / (fcam + sd)], "mm", ex("$\\dfrac1{s'}=\\dfrac1{50.0}-\\dfrac1{2000}\\Rightarrow s'=51.3\\,\\mathrm{mm}$: focusing moves the lens only slightly beyond the focal length (the image is real, inverted, $m=-0.026$)."), GEN(T34 + ", 34.50"), "gen", sig=3)
    mcq_num(B, c, "Thin lenses", 2, "A simple astronomical telescope has an objective of focal length $80.0\\,\\mathrm{cm}$ and an eyepiece of focal length $2.00\\,\\mathrm{cm}$. What is the magnitude of its angular magnification (viewing a distant object, final image at infinity)?", 80.0 / 2.0, [2.0 / 80.0, 80.0 + 2.0, 80.0 * 2.0, 80.0 - 2.0], "", ex("$M=\\dfrac{f_{obj}}{f_{eye}}=\\dfrac{80.0}{2.00}=40$ (the image is inverted; the lenses are $82\\,\\mathrm{cm}$ apart)."), GEN(LEC9 + " (optical instruments)"), "gen", sig=2)
    mcq_num(B, c, "Thin lenses", 2, "A real object is at a distance $2f$ in front of a converging lens. What is the magnification?", -1.0, [1.0, -2.0, 2.0, -0.5], "", ex("$\\dfrac1{s'}=\\dfrac1f-\\dfrac1{2f}=\\dfrac1{2f}\\Rightarrow s'=2f$ and $m=-\\dfrac{s'}{s}=-1$: a real, inverted image of the same size at $2f$."), GEN(T34 + ", 34.32"), "gen", sig=2)
    mcq_pick(B, c, "Thin lenses", 1, "In a principal-ray diagram for a thin lens, the ray that passes through the centre of the lens", ["continues undeviated", "emerges parallel to the axis", "passes through the focal point", "is reflected"], 0, ex("At the centre a thin lens is like a thin parallel plate, so the ray is not deviated. The ray parallel to the axis passes through the far focal point; the ray through the near focal point emerges parallel to the axis."), LEC9 + " (ray diagrams)", "concept")
    mcq_pick(B, c, "Plane and spherical mirrors", 1, "The image formed by a plane mirror is", ["virtual, erect and the same size, as far behind the mirror as the object is in front", "real and inverted", "virtual and magnified", "real and the same size"], 0, ex("For a plane mirror $s'=-s$ and $m=+1$."), LEC9 + " (plane mirrors)", "concept")
    mcq_pick(B, c, "Refraction at a surface", 2, "An object in water seen from the air above appears", ["closer to the surface than it really is", "deeper than it really is", "at its true depth", "larger but at the true depth"], 0, ex("Rays bend away from the normal on leaving the water, so they appear to come from a shallower point: $d_{app}=d\\dfrac{n_{air}}{n_{water}}=\\dfrac{d}{1.33}$."), LEC9 + " (refraction at a plane surface)", "concept")


# =============================================================================================== chapter 10
def ch10(B):
    c = "c10"
    # ---------------------------------------------------------------- 35.2 two radio antennas
    mcq_num(B, c, "Interference of waves", 2, "Two radio antennas A and B radiate in phase; B is $120\\,\\mathrm{m}$ to the right of A. A point Q lies on the line AB, $40\\,\\mathrm{m}$ to the right of B. What is the LONGEST wavelength for which the waves interfere destructively at Q?", 240.0, [120.0, 160.0, 80.0, 480.0], "m", ex("At Q the path difference is the separation of the antennas, $\\Delta=120\\,\\mathrm{m}$ (Q is on the line through both).", "Destructive: $\\Delta=\\left(m+\\tfrac12\\right)\\lambda$; the longest wavelength is for $m=0$: $\\lambda=2\\Delta=240\\,\\mathrm{m}$."), T35 + ", 35.2(a)", sig=3)
    mcq_num(B, c, "Interference of waves", 2, "For the same antennas ($120\\,\\mathrm{m}$ apart, Q on the line through them), what is the longest wavelength for CONSTRUCTIVE interference at Q?", 120.0, [240.0, 60.0, 160.0, 40.0], "m", ex("Constructive: $\\Delta=m\\lambda$ with $\\Delta=120\\,\\mathrm{m}$; the longest wavelength is for $m=1$: $\\lambda=120\\,\\mathrm{m}$ ($m=0$ would need $\\Delta=0$)."), T35 + ", 35.2(b)", sig=3)
    # ---------------------------------------------------------------- 35.6 double slit, near-centre spacing, high order
    lam, L, dy = 500 * NM, 2.00, 0.0353
    d = lam * L / dy
    y = lambda m: L * math.tan(math.asin(m * lam / d))
    exact = y(50) - y(49)
    ph = two_slit_intensity(d, lam, math.asin(lam / d)); check(ph, 1.0, 1e-9, "a bright fringe has full intensity (phasor sum)")
    mcq_num(B, c, "Young's double-slit experiment", 3, "Coherent light of wavelength $500\\,\\mathrm{nm}$ passes through two narrow slits. On a very tall screen $2.00\\,\\mathrm{m}$ away, adjacent maxima near the centre are $3.53\\,\\mathrm{cm}$ apart. What is the slit separation?", d, [lam * L / dy * 1000, lam * dy / L, lam / dy, d / 2], "m", ex("Near the centre $\\Delta y=\\dfrac{\\lambda L}{d}\\Rightarrow d=\\dfrac{\\lambda L}{\\Delta y}=\\dfrac{(500\\times10^{-9})(2.00)}{0.0353}=2.83\\times10^{-5}\\,\\mathrm{m}$ ($28\\,\\mu\\mathrm{m}$)."), T35 + ", 35.6", sig=3)
    mcq_num(B, c, "Young's double-slit experiment", 3, "With that slit separation ($28.3\\,\\mu\\mathrm{m}$, $\\lambda=500\\,\\mathrm{nm}$, screen $2.00\\,\\mathrm{m}$ away), how far apart on the screen are the $m=49$ and $m=50$ maxima? (Use the exact geometry: the angles are large.)", exact, [dy, dy * 2, exact * 2, exact / 2], "m", ex("Positions: $\\sin\\theta_m=\\dfrac{m\\lambda}{d}$ and $y_m=L\\tan\\theta_m$. For $m=49$: $\\sin\\theta=0.865$, $\\theta=59.9^\\circ$, $y=3.45\\,\\mathrm{m}$; for $m=50$: $\\sin\\theta=0.883$, $\\theta=62.0^\\circ$, $y=3.76\\,\\mathrm{m}$.", "Separation $=0.31\\,\\mathrm{m}$ - NOT the small-angle value $3.53\\,\\mathrm{cm}$: the fringes spread out at large angles."), T35 + ", 35.6", sig=2)
    # ---------------------------------------------------------------- 35.9 dark lines
    d9, L9, lam9 = 0.450e-3, 0.750, 500 * NM
    dy9 = lam9 * L9 / d9
    mcq_num(B, c, "Young's double-slit experiment", 2, "Two slits $0.450\\,\\mathrm{mm}$ apart are $75.0\\,\\mathrm{cm}$ from a screen and illuminated with $500\\,\\mathrm{nm}$ light. What is the distance between the second and third dark lines?", dy9, [dy9 * 2, dy9 / 2, dy9 * 2.5, lam9 * L9 * d9], "m", ex("Adjacent dark (and bright) fringes are equally spaced by $\\Delta y=\\dfrac{\\lambda L}{d}=\\dfrac{(500\\times10^{-9})(0.750)}{0.450\\times10^{-3}}=8.33\\times10^{-4}\\,\\mathrm{m}=0.833\\,\\mathrm{mm}$."), T35 + ", 35.9", sig=3)
    # ---------------------------------------------------------------- 35.11 number of fringes
    d11, lam11 = 0.0116e-3, 585 * NM
    mmax = int(d11 / lam11); nb = 2 * mmax + 1; thm = asin(mmax * lam11 / d11)
    mcq_num(B, c, "Young's double-slit experiment", 3, "Two thin parallel slits $0.0116\\,\\mathrm{mm}$ apart are illuminated by a laser beam of wavelength $585\\,\\mathrm{nm}$. On a very large distant screen, how many bright fringes are there in total (including the central one and those on both sides)?", nb, [mmax, 2 * mmax, 2 * mmax + 3, 2 * (mmax + 1) + 1], "", ex("Bright fringes: $d\\sin\\theta=m\\lambda$ with $|\\sin\\theta|\\le1$, so $|m|\\le\\dfrac d\\lambda=\\dfrac{11.6}{0.585}=19.8$, i.e. $m=0,\\pm1,\\dots,\\pm19$.", "Total $=2(19)+1=39$ fringes (no need to compute the angles)."), T35 + ", 35.11(a)", sig=3)
    mcq_num(B, c, "Young's double-slit experiment", 3, "For those slits ($0.0116\\,\\mathrm{mm}$, $585\\,\\mathrm{nm}$), at what angle from the original direction does the most distant fringe ($m=19$) occur?", thm, [asin(19 * lam11 / d11 / 2), 90.0, atan(19 * lam11 / d11), 19 * lam11 / d11 * 57.3 * 0.5], "deg", ex("$\\sin\\theta=\\dfrac{19(585\\times10^{-9})}{0.0116\\times10^{-3}}=0.958\\Rightarrow\\theta=73.4^\\circ$."), T35 + ", 35.11(b)", sig=3)
    # ---------------------------------------------------------------- 35.14 two wavelengths
    d14, L14 = 0.300e-3, 4.00
    y_r, y_b = 660 * NM * L14 / d14, 470 * NM * L14 / d14
    mcq_num(B, c, "Young's double-slit experiment", 2, "Light containing $660\\,\\mathrm{nm}$ (red) and $470\\,\\mathrm{nm}$ (blue) passes through two slits $0.300\\,\\mathrm{mm}$ apart; the screen is $4.00\\,\\mathrm{m}$ away. What is the distance between the first-order bright fringes of the two colours?", y_r - y_b, [y_r + y_b, y_r, (y_r - y_b) / 2, 660 * NM * L14 * d14], "m", ex("First order: $y=\\dfrac{\\lambda L}{d}$: red $8.80\\,\\mathrm{mm}$, blue $6.27\\,\\mathrm{mm}$ from the centre, same side.", "Separation $=8.80-6.27=2.53\\,\\mathrm{mm}=2.53\\times10^{-3}\\,\\mathrm{m}$."), T35 + ", 35.14", sig=3)
    # ---------------------------------------------------------------- 35.17 intensity and phase
    I_rel = cos(30.0) ** 2
    check(I_rel, two_slit_intensity(1.0, 1.0, math.asin(60.0 / 360.0)), 1e-9, "I = I0 cos^2(phi/2) by phasor addition")
    mcq_num(B, c, "Interference of waves", 2, "In a two-slit pattern the intensity at the peak of the central maximum is $I_0$. What fraction of $I_0$ is the intensity at a point where the phase difference between the two waves is $60.0^\\circ$?", I_rel, [cos(60.0) ** 2, cos(60.0), 0.5, cos(30.0)], "", ex("$I=I_0\\cos^2\\dfrac\\phi2=I_0\\cos^230.0^\\circ=0.750\\,I_0$ (phasor sum of two equal waves with $60^\\circ$ between them)."), T35 + ", 35.17(a)", sig=3)
    mcq_num(B, c, "Interference of waves", 2, "For $480\\,\\mathrm{nm}$ light, what path difference corresponds to a phase difference of $60.0^\\circ$?", 480 / 6.0, [480 / 3.0, 480 * 60.0, 480 / 12.0, 480 / 2.0], "nm", ex("$\\Delta=\\dfrac{\\phi}{2\\pi}\\lambda=\\dfrac{60^\\circ}{360^\\circ}(480\\,\\mathrm{nm})=80\\,\\mathrm{nm}$ ($\\lambda/6$)."), T35 + ", 35.17(b)", sig=3)
    d19, lam19 = 0.340e-3, 500 * NM
    phi19 = 2 * math.pi * d19 * sin(23.0) / lam19
    mcq_num(B, c, "Interference of waves", 2, "Coherent $500\\,\\mathrm{nm}$ light passes through narrow slits $0.340\\,\\mathrm{mm}$ apart. Far from the slits, what is the phase difference (in radians) of the light from the two slits at $23.0^\\circ$ from the centreline?", phi19, [phi19 / (2 * math.pi), 2 * math.pi * d19 * cos(23.0) / lam19, phi19 / 2, 2 * math.pi * d19 * 23.0 / lam19], "rad", ex("Path difference $d\\sin\\theta=(0.340\\times10^{-3})\\sin23.0^\\circ=1.33\\times10^{-4}\\,\\mathrm{m}$.", "$\\phi=\\dfrac{2\\pi\\,d\\sin\\theta}{\\lambda}=\\dfrac{2\\pi(1.33\\times10^{-4})}{500\\times10^{-9}}=1.67\\times10^{3}\\,\\mathrm{rad}$."), T35 + ", 35.19", sig=3)
    # ---------------------------------------------------------------- thin films: 35.26 / 35.35
    lam26, nf, tmin = 550.0, 1.70, 550.0 / (4 * 1.70)
    mcq_num(B, c, "Thin-film interference", 3, "A plastic film ($n=1.70$) is applied to a car window ($n=1.52$) to increase the reflectivity. What is the minimum film thickness for which $550\\,\\mathrm{nm}$ light (in air) reflected from the two sides interferes constructively?", tmin, [lam26 / (2 * nf), lam26 / (4 * nf) * 3, lam26 / 4, lam26 / (4 * 1.52)], "nm", ex("Reflection at air-film ($1.00<1.70$) gives a half-wave phase change; at film-glass ($1.70>1.52$) none. So the two reflected waves start $\\tfrac\\lambda2$ out of step, and constructive interference needs $2nt=\\left(m+\\tfrac12\\right)\\lambda$.", "Minimum ($m=0$): $t=\\dfrac{\\lambda}{4n}=\\dfrac{550}{4(1.70)}=81\\,\\mathrm{nm}$."), T35 + ", 35.26(a)", sig=3)
    mcq_num(B, c, "Thin-film interference", 3, "For the same film ($n=1.70$ on glass of $n=1.52$, $550\\,\\mathrm{nm}$), what is the NEXT greater thickness that also gives constructive reflection?", 3 * lam26 / (4 * nf), [lam26 / (2 * nf), 2 * lam26 / (4 * nf), lam26 / (4 * nf), 5 * lam26 / (4 * nf)], "nm", ex("$2nt=\\left(m+\\tfrac12\\right)\\lambda$ with $m=1$: $t=\\dfrac{3\\lambda}{4n}=\\dfrac{3(550)}{4(1.70)}=243\\,\\mathrm{nm}$ (thicknesses repeat every $\\dfrac{\\lambda}{2n}=162\\,\\mathrm{nm}$)."), T35 + ", 35.26(b)", sig=3)
    lam35, nc, ng = 550.0, 1.432, 1.62
    t35 = lam35 / (4 * nc)
    mcq_num(B, c, "Thin-film interference", 3, "Eyeglass lenses of index $1.62$ are coated with fluorite ($n=1.432$). What minimum coating thickness cancels $550\\,\\mathrm{nm}$ light reflected at normal incidence?", t35, [lam35 / (2 * nc), lam35 / (4 * ng), lam35 / 4, 3 * lam35 / (4 * nc)], "nm", ex("Both reflections (air-coating and coating-glass) occur from a denser medium, so both have a half-wave phase change: the waves are in phase before the path difference. Destructive interference needs $2nt=\\left(m+\\tfrac12\\right)\\lambda$.", "$t_{\\min}=\\dfrac{\\lambda}{4n}=\\dfrac{550}{4(1.432)}=96.0\\,\\mathrm{nm}$ (an anti-reflection coating)."), T35 + ", 35.35(a)", sig=3)
    mcq_num(B, c, "Thin-film interference", 3, "A soap film ($n=1.33$) in air is illuminated by $589\\,\\mathrm{nm}$ light at normal incidence. What is the thinnest film that appears bright in reflection?", 589.0 / (4 * 1.33), [589.0 / (2 * 1.33), 589.0 / 1.33, 589.0 / 4, 3 * 589.0 / (4 * 1.33)], "nm", ex("Only the front reflection has a half-wave phase change (air-soap), so bright reflection needs $2nt=\\left(m+\\tfrac12\\right)\\lambda$: $t_{\\min}=\\dfrac{\\lambda}{4n}=\\dfrac{589}{4(1.33)}=111\\,\\mathrm{nm}$."), GEN(T35 + ", 35.26"), "gen", sig=3)
    mcq_num(B, c, "Thin-film interference", 3, "A thin air wedge between two glass plates is lit by $600\\,\\mathrm{nm}$ light at normal incidence. What is the air gap at the second dark fringe after the contact line (counting the contact line as the zeroth dark fringe)?", 2 * 600.0 / 2, [600.0 / 2, 600.0 / 4, 600.0, 3 * 600.0 / 2], "nm", ex("One reflection (from the lower plate) has a half-wave phase change, so dark fringes need $2t=m\\lambda$: $t=m\\dfrac\\lambda2$. For $m=2$: $t=\\lambda=600\\,\\mathrm{nm}$ (the contact line, $t=0$, is dark: $m=0$)."), GEN(T35 + ", 35.26"), "gen", sig=3)
    # ---------------------------------------------------------------- generated double slit
    for dd, LL, ll in [(0.20e-3, 1.50, 600 * NM), (0.50e-3, 2.00, 450 * NM)]:
        dyg = ll * LL / dd
        mcq_num(B, c, "Young's double-slit experiment", 2, "Light of wavelength %s nm falls on two slits %s mm apart. What is the spacing of the bright fringes on a screen %s m away?" % (sci(ll / NM), sci(dd * 1e3), sci(LL)), dyg * 1e3, [ll * LL * dd * 1e3, dd * LL / ll * 1e3 * 1e-6, dyg * 1e3 * 2, dyg * 1e3 / 2], "mm", ex("$\\Delta y=\\dfrac{\\lambda L}{d}=\\dfrac{(%s\\times10^{-9})(%s)}{%s\\times10^{-3}}=%s\\,\\mathrm{mm}$." % (sci(ll / NM), sci(LL), sci(dd * 1e3), sci(dyg * 1e3))), GEN(T35 + ", 35.9"), "gen", sig=3)
    mcq_num(B, c, "Young's double-slit experiment", 2, "In a double-slit experiment with $500\\,\\mathrm{nm}$ light the third bright fringe ($m=3$) is observed at $7.5\\,\\mathrm{mm}$ from the centre on a screen $2.0\\,\\mathrm{m}$ away. What is the slit separation (small angles)?", 3 * 500 * NM * 2.0 / 7.5e-3, [500 * NM * 2.0 / 7.5e-3, 3 * 500 * NM * 7.5e-3 / 2.0, 3 * 500 * NM / (2.0 * 7.5e-3), 3 * 500 * NM * 2.0 / 7.5e-3 * 2], "m", ex("$y_m=\\dfrac{m\\lambda L}{d}\\Rightarrow d=\\dfrac{3(500\\times10^{-9})(2.0)}{7.5\\times10^{-3}}=4.0\\times10^{-4}\\,\\mathrm{m}$."), GEN(T35 + ", 35.6"), "gen", sig=2)
    mcq_pick(B, c, "Young's double-slit experiment", 1, "In Young's experiment, replacing red light by blue light (shorter wavelength) and changing nothing else makes the fringes", ["closer together", "farther apart", "unchanged in spacing", "disappear"], 0, ex("$\\Delta y=\\dfrac{\\lambda L}{d}\\propto\\lambda$: a smaller wavelength gives a smaller fringe spacing."), LEC10 + " (double-slit)", "concept")
    mcq_pick(B, c, "Young's double-slit experiment", 1, "The condition for a BRIGHT fringe in a double-slit experiment is", ["$d\\sin\\theta=m\\lambda$", "$d\\sin\\theta=\\left(m+\\tfrac12\\right)\\lambda$", "$d\\cos\\theta=m\\lambda$", "$d\\tan\\theta=m\\lambda/2$"], 0, ex("Path difference $d\\sin\\theta$ equal to a whole number of wavelengths gives constructive interference; a half-integer number gives dark fringes."), LEC10 + " (double-slit)", "concept")
    mcq_pick(B, c, "Interference of waves", 1, "Two light sources are coherent if", ["they have a constant phase relationship", "they have different frequencies", "they are very bright", "they are far apart"], 0, ex("Stable interference fringes need a fixed phase difference, which two independent bulbs do not have; the two slits are fed by the SAME wave."), LEC10 + " (coherence)", "concept")
    mcq_pick(B, c, "Thin-film interference", 2, "A light wave reflecting from a boundary where it goes from a lower to a higher refractive index undergoes a phase change of", ["$\\pi$ ($180^\\circ$)", "$0$", "$\\pi/2$", "$2\\pi$"], 0, ex("Reflection off a denser medium inverts the wave (like a pulse on a string tied to a wall). Reflection off a less dense medium does not."), LEC10 + " (thin films)", "concept")
    mcq_pick(B, c, "Interference of waves", 2, "When two waves of equal amplitude interfere destructively, the intensity at that point is", ["zero", "half the single-wave intensity", "the same as one wave", "twice the single-wave intensity"], 0, ex("Amplitudes cancel, $I\\propto A^2=0$; energy is redistributed to the bright fringes (constructive: $4I_1$)."), LEC10 + " (interference)", "concept")

# =============================================================================================== chapter 11
def ch11(B):
    c = "c11"
    # ---------------------------------------------------------------- 36.1
    a1, L1, y1 = 0.750e-3, 2.00, 1.35e-3
    lam1 = a1 * y1 / L1
    mcq_num(B, c, "Single-slit diffraction", 2, "Monochromatic light passes through a slit $0.750\\,\\mathrm{mm}$ wide. On a screen $2.00\\,\\mathrm{m}$ away, the first minimum is $1.35\\,\\mathrm{mm}$ from the central maximum. What is the wavelength?", lam1 / NM, [lam1 / NM * 2, lam1 / NM / 2, a1 * L1 / y1 / NM, y1 * L1 / a1 / NM], "nm", ex("First minimum: $a\\sin\\theta=\\lambda$ with $\\sin\\theta\\approx\\dfrac yL$: $\\lambda=\\dfrac{ay}{L}=\\dfrac{(0.750\\times10^{-3})(1.35\\times10^{-3})}{2.00}=5.06\\times10^{-7}\\,\\mathrm{m}=506\\,\\mathrm{nm}$."), T36 + ", 36.1", sig=3)
    # ---------------------------------------------------------------- 36.6 tsunami
    lamt = 800.0 * 1.0
    s1, s2 = asin(lamt / 4500.0), asin(lamt / 3700.0)
    mcq_num(B, c, "Single-slit diffraction", 3, "A tsunami has wave crests $1.0\\,\\mathrm{h}$ apart and speed $800\\,\\mathrm{km/h}$. What is its wavelength?", lamt, [lamt / 3600, lamt * 3600, lamt / 2, 800.0 / 3.6], "km", ex("$\\lambda=vT=(800\\,\\mathrm{km/h})(1.0\\,\\mathrm{h})=800\\,\\mathrm{km}$."), T36 + ", 36.6(a)", sig=2)
    mcq_num(B, c, "Single-slit diffraction", 3, "The tsunami (wavelength $800\\,\\mathrm{km}$) passes through the $4500\\,\\mathrm{km}$ gap between Africa and Antarctica, modelled as a slit. What is the smallest angle from the central maximum at which the waves cancel?", s1, [asin(lamt / 4500.0 / 2), atan(4500.0 / lamt), 90.0 - s1, asin(lamt / 3700.0)], "deg", ex("First minimum: $a\\sin\\theta=\\lambda\\Rightarrow\\sin\\theta=\\dfrac{800}{4500}=0.178\\Rightarrow\\theta=10.2^\\circ$ (for the narrower $3700\\,\\mathrm{km}$ gap: $12.5^\\circ$)."), T36 + ", 36.6(b)", sig=3)
    # ---------------------------------------------------------------- 36.8 width of the central maximum
    w, L8 = 6.00e-3, 2.50
    a8 = 2 * 500 * NM * L8 / w
    mcq_num(B, c, "Single-slit diffraction", 2, "The central maximum of a single-slit pattern on a screen $2.50\\,\\mathrm{m}$ from the slit is $6.00\\,\\mathrm{mm}$ wide. What is the slit width for $500\\,\\mathrm{nm}$ visible light?", a8, [a8 / 2, a8 * 2, 500 * NM * L8 / w * 4, 500 * NM * w / L8], "m", ex("Width of the central maximum $=2y_1=\\dfrac{2\\lambda L}{a}\\Rightarrow a=\\dfrac{2\\lambda L}{w}=\\dfrac{2(500\\times10^{-9})(2.50)}{6.00\\times10^{-3}}=4.17\\times10^{-4}\\,\\mathrm{m}$ ($0.417\\,\\mathrm{mm}$)."), T36 + ", 36.8(a)", sig=3)
    # ---------------------------------------------------------------- 36.14 intensity in the single-slit pattern
    a14, lam14, L14 = 0.450e-3, 620 * NM, 3.00
    for y_mm in (1.00, 3.00, 5.00):
        th = math.atan(y_mm * 1e-3 / L14); b = math.pi * a14 * math.sin(th) / lam14
        rel = (math.sin(b) / b) ** 2
        check(rel, slit_intensity(a14, lam14, th), 1e-5, "single-slit intensity by integrating the wavelets across the slit")
        mcq_num(B, c, "Single-slit diffraction", 3, "Light of wavelength $620\\,\\mathrm{nm}$ passes through a slit $0.450\\,\\mathrm{mm}$ wide; the screen is $3.00\\,\\mathrm{m}$ away. In terms of the central intensity $I_0$, what is the intensity at %s mm from the centre?" % sci(y_mm), rel, [math.sin(b) / b, 1.0 - rel, (math.sin(b)) ** 2, rel / 2], "I_0", ex("$I=I_0\\left(\\dfrac{\\sin\\beta}{\\beta}\\right)^2$ with $\\beta=\\dfrac{\\pi a\\sin\\theta}{\\lambda}\\approx\\dfrac{\\pi ay}{\\lambda L}=%s\\,\\mathrm{rad}$." % sci(b), "$I=%s\\,I_0$. (Numerical integration of the wavelets across the slit reproduces this value; $\\beta$ must be in radians.)" % sci(rel)), T36 + ", 36.14", sig=3)
    # ---------------------------------------------------------------- 36.15 radio waves between buildings
    lam15 = C / 88.9e6; a15 = 15.0
    th1 = asin(lam15 / a15); th5 = 5.00
    b5 = math.pi * a15 * sin(th5) / lam15
    I5 = 3.50 * (math.sin(b5) / b5) ** 2
    mcq_num(B, c, "Single-slit diffraction", 3, "FM radio waves ($88.9\\,\\mathrm{MHz}$) pass between two skyscrapers $15.0\\,\\mathrm{m}$ apart. At what smallest horizontal angle from the original direction will a distant antenna receive NO signal?", th1, [asin(lam15 / a15 / 2), asin(2 * lam15 / a15), atan(lam15 / a15), lam15 / a15], "deg", ex("$\\lambda=\\dfrac cf=3.37\\,\\mathrm{m}$. Minima of the single-slit pattern: $a\\sin\\theta=m\\lambda$; the first is $\\sin\\theta=\\dfrac{3.37}{15.0}=0.225\\Rightarrow\\theta=13.0^\\circ$ (also at $\\pm26.7^\\circ$, $\\pm42.4^\\circ$, ...)."), T36 + ", 36.15(a)", sig=3)
    mcq_num(B, c, "Single-slit diffraction", 3, "For those radio waves the maximum intensity at the antenna is $3.50\\,\\mathrm{W/m^2}$. What is the intensity at $\\pm5.00^\\circ$ from the centre of the central maximum?", I5, [3.50 * (math.sin(b5) / b5), 3.50 / 2, 3.50 * (1.0 - (math.sin(b5) / b5) ** 2), 3.50 * (math.sin(b5)) ** 2], "W/m^2", ex("$\\beta=\\dfrac{\\pi a\\sin\\theta}{\\lambda}=\\dfrac{\\pi(15.0)\\sin5.00^\\circ}{3.37}=1.22\\,\\mathrm{rad}$.", "$I=I_{\\max}\\left(\\dfrac{\\sin\\beta}{\\beta}\\right)^2=3.50\\left(\\dfrac{0.938}{1.22}\\right)^2=2.1\\,\\mathrm{W/m^2}$."), T36 + ", 36.15(b)", sig=2)
    # ---------------------------------------------------------------- 36.19 fringes in the central diffraction maximum
    mcq_num(B, c, "Combined interference and diffraction", 3, "In a double-slit experiment the central diffraction maximum contains exactly seven interference fringes when $d/a=4$. What must $d/a$ be if the central maximum contains exactly FIVE fringes?", 3.0, [2.0, 4.0, 2.5, 5.0], "", ex("The central diffraction maximum ends at $a\\sin\\theta=\\lambda$, where the interference order is $m=\\dfrac da$. The orders strictly inside are $m=-(d/a-1),\\dots,+(d/a-1)$: $2\\dfrac da-1$ fringes.", "$7=2(4)-1$ ✓; for five fringes $2\\dfrac da-1=5\\Rightarrow\\dfrac da=3$."), T36 + ", 36.19(a)", sig=2)
    mcq_num(B, c, "Combined interference and diffraction", 3, "In the case $d/a=3$ (five fringes in the central diffraction maximum), how many interference fringes lie inside the FIRST diffraction side maximum on one side?", 2, [1, 3, 4, 5], "", ex("With $d=3a$ the orders $m=\\pm3,\\pm6$ coincide with diffraction minima and are missing. The first side maximum lies between $a\\sin\\theta=\\lambda$ and $2\\lambda$, i.e. orders $m=3$ to $6$, exclusive of the missing ones: $m=4$ and $m=5$ - two fringes."), T36 + ", 36.19(b)", sig=2)
    # ---------------------------------------------------------------- 36.21 two finite slits
    d21, lam21 = 0.530e-3, 580 * NM
    t1, t2 = asin(lam21 / d21), asin(2 * lam21 / d21)
    mcq_num(B, c, "Combined interference and diffraction", 2, "Two very narrow slits $0.530\\,\\mathrm{mm}$ apart are lit by $580\\,\\mathrm{nm}$ light. At what angle is the FIRST-order interference maximum?", t1, [asin(lam21 / d21 * 2), asin(lam21 / (2 * d21)), atan(d21 / lam21), t1 * 2], "deg", ex("$d\\sin\\theta=m\\lambda$: $\\sin\\theta_1=\\dfrac{580\\times10^{-9}}{0.530\\times10^{-3}}=1.09\\times10^{-3}\\Rightarrow\\theta_1=0.0627^\\circ$ (and $\\theta_2=0.125^\\circ$ for $m=2$)."), T36 + ", 36.21(a)", sig=3)
    # ---------------------------------------------------------------- 36.26, 36.31 gratings
    t4 = asin(4 * sin(11.3))
    mcq_num(B, c, "Diffraction gratings", 2, "Monochromatic light is at normal incidence on a plane transmission grating. The first-order maximum is at $11.3^\\circ$. At what angle is the FOURTH-order maximum?", t4, [4 * 11.3, asin(2 * sin(11.3)), asin(sin(11.3) / 4), atan(4 * tan(11.3))], "deg", ex("$\\sin\\theta_m=m\\dfrac\\lambda d$: $\\sin\\theta_4=4\\sin11.3^\\circ=0.784\\Rightarrow\\theta_4=51.6^\\circ$. The angle is NOT four times larger ($45.2^\\circ$)."), T36 + ", 36.26", sig=3)
    d31 = 1 / 5000.0 * 1e-2
    lam31 = d31 * sin(13.5)
    mcq_num(B, c, "Diffraction gratings", 2, "A transmission grating has $5000$ slits per centimetre. What wavelength is deviated through $13.5^\\circ$ in the first order (normal incidence)?", lam31 / NM, [d31 / NM * sin(13.5) * 2, d31 / NM * cos(13.5), 1 / 5000.0 / NM * sin(13.5), d31 / NM * tan(13.5)], "nm", ex("Slit spacing $d=\\dfrac{1\\,\\mathrm{cm}}{5000}=2.00\\,\\mu\\mathrm{m}$. $\\lambda=d\\sin\\theta=(2.00\\times10^{-6})\\sin13.5^\\circ=467\\,\\mathrm{nm}$ (blue-violet)."), T36 + ", 36.31(a)", sig=3)
    mcq_num(B, c, "Diffraction gratings", 2, "For that grating ($5000$ slits/cm) and the $467\\,\\mathrm{nm}$ light, what is the second-order deviation?", asin(2 * lam31 / d31), [2 * 13.5, asin(lam31 / (2 * d31)), asin(3 * lam31 / d31), 13.5], "deg", ex("$\\sin\\theta_2=\\dfrac{2\\lambda}{d}=\\dfrac{2(467\\times10^{-9})}{2.00\\times10^{-6}}=0.467\\Rightarrow\\theta_2=27.8^\\circ$."), T36 + ", 36.31(b)", sig=3)
    # ---------------------------------------------------------------- 36.33 resolving the isotopes
    l1, l2 = 656.45, 656.27
    Nmin = (l1 + l2) / 2 / (l1 - l2) / 2
    mcq_num(B, c, "Diffraction gratings", 3, "A wavelength of $656.45\\,\\mathrm{nm}$ in hydrogen and $656.27\\,\\mathrm{nm}$ in deuterium must be resolved in SECOND order. What minimum number of slits is needed? ($R=\\lambda/\\Delta\\lambda=Nm$)", Nmin, [Nmin * 2, Nmin / 2, (l1 + l2) / 2 / (l1 - l2), Nmin * 4], "", ex("Resolving power $R=\\dfrac{\\lambda}{\\Delta\\lambda}=Nm\\Rightarrow N=\\dfrac{656.36}{(0.18)(2)}=1.82\\times10^{3}$ slits."), T36 + ", 36.33(a)", sig=3)
    d33 = 1e-3 / 500.0
    ang1, ang2 = asin(2 * l1 * NM / d33), asin(2 * l2 * NM / d33)
    mcq_num(B, c, "Diffraction gratings", 3, "A grating with $500.00\\,\\mathrm{slits/mm}$ is used in second order. What is the angle of the $656.45\\,\\mathrm{nm}$ line?", ang1, [asin(l1 * NM / d33), 2 * asin(l1 * NM / d33), asin(2 * l1 * NM / d33 / 2), 90.0 - ang1], "deg", ex("$d=\\dfrac{1\\,\\mathrm{mm}}{500}=2.000\\,\\mu\\mathrm{m}$; $\\sin\\theta=\\dfrac{2\\lambda}{d}=\\dfrac{2(656.45\\times10^{-9})}{2.000\\times10^{-6}}=0.6565\\Rightarrow\\theta=41.03^\\circ$ (the deuterium line is at $41.02^\\circ$: only $0.014^\\circ$ apart)."), T36 + ", 36.33(b)", sig=4)
    # ---------------------------------------------------------------- 36.36 Bragg, 36.37 Airy disk
    lamB = 2 * 0.440 * sin(39.4)
    mcq_num(B, c, "X-ray diffraction", 2, "Monochromatic X-rays reflect from crystal planes $0.440\\,\\mathrm{nm}$ apart; the first-order Bragg maximum occurs when the beam makes $39.4^\\circ$ with the planes. What is the X-ray wavelength?", lamB, [0.440 * sin(39.4), 2 * 0.440 * cos(39.4), 0.440 / (2 * sin(39.4)), 2 * 0.440 * sin(2 * 39.4)], "nm", ex("Bragg's law: $2d\\sin\\theta=m\\lambda$, with $\\theta$ measured from the PLANES: $\\lambda=2(0.440)\\sin39.4^\\circ=0.559\\,\\mathrm{nm}$."), T36 + ", 36.36", sig=3)
    lam37, D37, L37 = 620 * NM, 7.4e-6, 4.5
    airy = 2 * 1.22 * lam37 * L37 / D37
    mcq_num(B, c, "Circular apertures and resolution", 2, "Light of wavelength $620\\,\\mathrm{nm}$ passes through a circular aperture of diameter $7.4\\,\\mu\\mathrm{m}$ onto a screen $4.5\\,\\mathrm{m}$ away. What is the diameter of the central bright spot (Airy disk)?", airy, [airy / 2, airy * 1.22 / 2.44 * 1.0, 2 * lam37 * L37 / D37, 1.22 * lam37 * L37 / D37 * 4], "m", ex("The first dark ring is at $\\sin\\theta=1.22\\dfrac\\lambda D$, so the disk diameter is $2L\\tan\\theta\\approx\\dfrac{2.44\\lambda L}{D}=\\dfrac{2.44(620\\times10^{-9})(4.5)}{7.4\\times10^{-6}}=0.92\\,\\mathrm{m}$ (the factor 1.22 replaces 1 because the aperture is circular)."), T36 + ", 36.37", sig=2)
    # ---------------------------------------------------------------- 36.39 satellites, 36.42 camera, 36.43 telescopes, 36.45 hair
    th39 = 28.0 / 1200.0
    D39 = 1.22 * 0.036 / th39
    mcq_num(B, c, "Circular apertures and resolution", 2, "Two satellites at an altitude of $1200\\,\\mathrm{km}$ are $28\\,\\mathrm{km}$ apart and broadcast $3.6\\,\\mathrm{cm}$ microwaves. What minimum dish diameter resolves them (Rayleigh's criterion)?", D39, [0.036 / th39, 1.22 * 0.036 * th39, D39 / 2, 2.44 * 0.036 / th39], "m", ex("Angular separation $\\theta=\\dfrac{28}{1200}=0.0233\\,\\mathrm{rad}$. Rayleigh: $\\theta=1.22\\dfrac\\lambda D\\Rightarrow D=\\dfrac{1.22(0.036)}{0.0233}=1.9\\,\\mathrm{m}$."), T36 + ", 36.39", sig=2)
    f42, Fn, R42, lam42 = 135e-3, 4.00, 11.5, 550 * NM
    D4 = f42 / Fn; D22 = f42 / 22.0
    s4 = 1.22 * lam42 * R42 / D4; s22 = 1.22 * lam42 * R42 / D22
    mcq_num(B, c, "Circular apertures and resolution", 3, "A telephoto lens of focal length $135\\,\\mathrm{mm}$ is opened to $f/4.00$ (aperture diameter $f/N$). Photographing a bear $11.5\\,\\mathrm{m}$ away with $550\\,\\mathrm{nm}$ light, what is the width of the smallest resolvable feature on the bear?", s4, [s22, 1.22 * lam42 * R42 / f42, s4 / 4, s4 * 4], "m", ex("Aperture $D=\\dfrac{135\\,\\mathrm{mm}}{4.00}=33.8\\,\\mathrm{mm}$. Resolution: $s=R\\,\\theta=R\\,\\dfrac{1.22\\lambda}{D}=\\dfrac{(11.5)(1.22)(550\\times10^{-9})}{0.0338}=2.3\\times10^{-4}\\,\\mathrm{m}=0.23\\,\\mathrm{mm}$."), T36 + ", 36.42(a)", sig=2)
    mcq_num(B, c, "Circular apertures and resolution", 3, "The same photographer stops the lens down to $f/22.0$. What is the width of the smallest resolvable feature on the bear (same distance and wavelength)?", s22, [s4, s22 / 5.5, s22 * 5.5, 1.22 * lam42 * R42 / D22 * 22.0], "m", ex("$D=\\dfrac{135}{22.0}=6.14\\,\\mathrm{mm}$ gives $s=\\dfrac{(11.5)(1.22)(550\\times10^{-9})}{6.14\\times10^{-3}}=1.3\\times10^{-3}\\,\\mathrm{m}=1.3\\,\\mathrm{mm}$: more depth of field, less resolution (about $5.5$ times coarser)."), T36 + ", 36.42(b)", sig=2)
    Dm, dm = 2.4, 3.84e8
    crater = 1.22 * 380 * NM / Dm * dm
    mcq_num(B, c, "Circular apertures and resolution", 3, "The Hubble Space Telescope has a $2.4\\,\\mathrm{m}$ aperture. For $380\\,\\mathrm{nm}$ light, what is the smallest crater it can resolve on the Moon ($3.84\\times10^{8}\\,\\mathrm{m}$ away)?", crater, [1.22 * 750 * NM / Dm * dm, crater / 1.22, 1.22 * 380 * NM / Dm, crater * 10], "m", ex("$\\theta_{\\min}=1.22\\dfrac{\\lambda}{D}=1.22\\dfrac{380\\times10^{-9}}{2.4}=1.9\\times10^{-7}\\,\\mathrm{rad}$; width $=\\theta d=(1.9\\times10^{-7})(3.84\\times10^8)=74\\,\\mathrm{m}$ (about $140\\,\\mathrm{m}$ with red light)."), T36 + ", 36.43(a)", sig=2)
    y45, L45, lam45 = 5.22e-2 / 2, 1.25, 632.8 * NM
    a45 = lam45 * L45 / y45
    mcq_num(B, c, "Single-slit diffraction", 3, "A beam of wavelength $632.8\\,\\mathrm{nm}$ is shone on a single strand of hair; on a screen $1.25\\,\\mathrm{m}$ away the first dark fringes on either side of the central spot are $5.22\\,\\mathrm{cm}$ apart. How thick is the hair?", a45, [lam45 * L45 / (2 * y45), 2 * lam45 * L45 / y45, lam45 * y45 / L45, lam45 * L45 / 5.22e-2 * 2], "m", ex("The first minima are $\\pm y$ with $y=\\dfrac{5.22}{2}\\,\\mathrm{cm}=2.61\\,\\mathrm{cm}$ from the centre (the 5.22 cm is the distance between BOTH).", "$a=\\dfrac{\\lambda L}{y}=\\dfrac{(632.8\\times10^{-9})(1.25)}{0.0261}=3.03\\times10^{-5}\\,\\mathrm{m}=30\\,\\mu\\mathrm{m}$."), T36 + ", 36.45", sig=3)
    # ---------------------------------------------------------------- generated
    for aa, ll, LL in [(0.20e-3, 600 * NM, 1.5), (0.050e-3, 500 * NM, 2.0)]:
        wc = 2 * ll * LL / aa
        mcq_num(B, c, "Single-slit diffraction", 2, "Light of wavelength %s nm passes through a slit of width %s mm. What is the width of the central maximum on a screen %s m away?" % (sci(ll / NM), sci(aa * 1e3), sci(LL)), wc * 1e3, [wc * 1e3 / 2, wc * 1e3 * 2, ll * LL / aa * 1e3 * 1.22, aa * LL / ll * 1e-3], "mm", ex("The central maximum extends between the first minima: $w=\\dfrac{2\\lambda L}{a}=\\dfrac{2(%s\\times10^{-9})(%s)}{%s\\times10^{-3}}=%s\\,\\mathrm{mm}$ (twice the distance to the first minimum)." % (sci(ll / NM), sci(LL), sci(aa * 1e3), sci(wc * 1e3))), GEN(T36 + ", 36.8"), "gen", sig=3)
    mcq_num(B, c, "Circular apertures and resolution", 2, "The pupil of the eye is $3.0\\,\\mathrm{mm}$ across. What is the smallest angular separation it can resolve at $550\\,\\mathrm{nm}$ (Rayleigh criterion)?", 1.22 * 550 * NM / 3.0e-3, [550 * NM / 3.0e-3, 1.22 * 3.0e-3 / (550 * NM), 2.44 * 550 * NM / 3.0e-3, 1.22 * 550 * NM / 3.0e-3 / 2], "rad", ex("$\\theta_{\\min}=1.22\\dfrac\\lambda D=1.22\\dfrac{550\\times10^{-9}}{3.0\\times10^{-3}}=2.2\\times10^{-4}\\,\\mathrm{rad}$ (about $0.77$ arc-minutes)."), GEN(T36 + ", 36.39"), "gen", sig=2)
    mcq_pick(B, c, "Single-slit diffraction", 1, "If the width of a single slit is halved (same light, same screen), the central diffraction maximum becomes", ["twice as wide", "half as wide", "unchanged", "four times narrower"], 0, ex("$w=\\dfrac{2\\lambda L}{a}\\propto\\dfrac1a$: a narrower slit spreads the light more."), LEC11 + " (single slit)", "concept")
    mcq_pick(B, c, "Single-slit diffraction", 1, "The condition for the MINIMA of a single-slit diffraction pattern is", ["$a\\sin\\theta=m\\lambda$, $m=\\pm1,\\pm2,\\dots$", "$a\\sin\\theta=\\left(m+\\tfrac12\\right)\\lambda$", "$a\\cos\\theta=m\\lambda$", "$a\\sin\\theta=0$ only"], 0, ex("Dark fringes occur when the path difference between the two edges is a whole number of wavelengths (each half of the slit then cancels the other half). Do not confuse with the double-slit MAXIMA, $d\\sin\\theta=m\\lambda$."), LEC11 + " (single slit)", "concept")
    mcq_pick(B, c, "Diffraction gratings", 1, "A diffraction grating gives sharper and brighter maxima than a double slit because", ["many slits interfere constructively only in very narrow angular ranges", "its slits are wider", "it uses a longer wavelength", "the light is polarised"], 0, ex("With $N$ slits the maxima have the same positions $d\\sin\\theta=m\\lambda$ but their angular width falls as $1/N$ and their intensity grows as $N^2$."), LEC11 + " (gratings)", "concept")
    mcq_pick(B, c, "Diffraction gratings", 2, "White light falls on a grating. In the first-order spectrum the colour deviated through the LARGEST angle is", ["red", "violet", "green", "all colours the same"], 0, ex("$\\sin\\theta=\\dfrac{\\lambda}{d}$: the longest wavelength (red) deviates most; this is the opposite of a prism, where violet bends more."), LEC11 + " (gratings)", "concept")
    mcq_pick(B, c, "Circular apertures and resolution", 1, "To resolve two nearby point sources better with a telescope one should", ["increase the aperture diameter", "decrease the aperture diameter", "use longer-wavelength light", "move the sources apart in colour"], 0, ex("$\\theta_{\\min}=1.22\\dfrac\\lambda D$ decreases when $D$ increases or $\\lambda$ decreases."), LEC11 + " (resolution)", "concept")


def ch10b(B):
    c = "c10"
    # oil film on water: both reflections have a half-wave change, so bright when 2 n t = m lambda
    n_o, t_o = 1.20, 460.0
    lam_b = 2 * n_o * t_o / 2
    mcq_num(B, c, "Thin-film interference", 3, "An oil film ($n=1.20$) $460\\,\\mathrm{nm}$ thick floats on water ($n=1.33$). In normal incidence, which visible wavelength (in nm) is most strongly reflected?", lam_b, [4 * n_o * t_o / 3, 2 * t_o, 4 * t_o / 3 * 0.9, 2 * n_o * t_o], "nm", ex("Air-oil ($1.00<1.20$) and oil-water ($1.20<1.33$) are both reflections from a DENSER medium: both waves get a half-wave change, so there is no net phase difference. Bright reflection: $2nt=m\\lambda$.", "$\\lambda=\\dfrac{2(1.20)(460)}{m}=\\dfrac{1104}{m}$: $1104\\,\\mathrm{nm}$ (infrared, $m=1$), $552\\,\\mathrm{nm}$ (green, $m=2$), $368\\,\\mathrm{nm}$ (ultraviolet, $m=3$). Only $552\\,\\mathrm{nm}$ is visible."), GEN(T35 + ", 35.26"), "gen", sig=3)
    mcq_num(B, c, "Thin-film interference", 2, "A magnesium fluoride coating ($n=1.38$) on a lens ($n=1.52$) is meant to reduce reflection of $600\\,\\mathrm{nm}$ light. What is the minimum coating thickness?", 600.0 / (4 * 1.38), [600.0 / (2 * 1.38), 600.0 / 4, 600.0 / (4 * 1.52), 3 * 600.0 / (4 * 1.38)], "nm", ex("Both reflections come from denser media, so destructive interference needs $2nt=\\left(m+\\tfrac12\\right)\\lambda$: $t_{\\min}=\\dfrac{\\lambda}{4n}=\\dfrac{600}{4(1.38)}=109\\,\\mathrm{nm}$."), GEN(T35 + ", 35.35"), "gen", sig=3)
    mcq_num(B, c, "Young's double-slit experiment", 2, "A double-slit experiment with $500\\,\\mathrm{nm}$ light (in air) shows a fringe spacing of $2.4\\,\\mathrm{mm}$. If the whole apparatus is immersed in water ($n=1.33$), what is the new fringe spacing?", 2.4 / 1.33, [2.4 * 1.33, 2.4, 2.4 / 1.33 ** 2, 2.4 / 0.33], "mm", ex("In water the wavelength becomes $\\lambda/n$, and $\\Delta y=\\dfrac{\\lambda L}{d}$ shrinks by the same factor: $\\dfrac{2.4}{1.33}=1.8\\,\\mathrm{mm}$."), GEN(T35 + ", 35.9"), "gen", sig=2)
    mcq_num(B, c, "Young's double-slit experiment", 3, "A thin transparent film of thickness $5.0\\,\\mu\\mathrm{m}$ and index $1.50$ is placed over ONE slit of a double-slit apparatus lit by $500\\,\\mathrm{nm}$ light. By how many fringes does the pattern shift?", (1.50 - 1.0) * 5.0e-6 / (500 * NM), [1.50 * 5.0e-6 / (500 * NM), 5.0e-6 / (500 * NM), (1.50 - 1.0) * 5.0e-6 / (500 * NM) * 2, (1.50 + 1.0) * 5.0e-6 / (500 * NM)], "", ex("The film adds an optical path $nt$ in place of $t$ of air: extra path $(n-1)t=(0.50)(5.0\\,\\mu\\mathrm{m})=2.5\\,\\mu\\mathrm{m}$.", "Shift $=\\dfrac{(n-1)t}{\\lambda}=\\dfrac{2.5\\times10^{-6}}{500\\times10^{-9}}=5.0$ fringes."), GEN(T35 + ", 35.4"), "gen", sig=2)
    mcq_num(B, c, "Interference of waves", 3, "Two loudspeakers $3.00\\,\\mathrm{m}$ apart emit the same $686\\,\\mathrm{Hz}$ tone in phase (speed of sound $343\\,\\mathrm{m/s}$). A listener is $4.00\\,\\mathrm{m}$ directly in front of one speaker. What is the path difference to the two speakers, in wavelengths?", (math.hypot(4.0, 3.0) - 4.0) / (343.0 / 686.0), [(math.hypot(4.0, 3.0) + 4.0) / (343.0 / 686.0), (math.hypot(4.0, 3.0) - 4.0), 3.0 / (343.0 / 686.0), (math.hypot(4.0, 3.0) - 4.0) / (343.0 / 686.0) / 2], "", ex("$\\lambda=\\dfrac vf=\\dfrac{343}{686}=0.500\\,\\mathrm{m}$. Distances: $4.00\\,\\mathrm{m}$ and $\\sqrt{4.00^2+3.00^2}=5.00\\,\\mathrm{m}$.", "Path difference $=1.00\\,\\mathrm{m}=2\\lambda$: a whole number, so the interference is CONSTRUCTIVE (a loud spot)."), GEN(T35 + ", 35.3"), "gen", sig=2)
    mcq_num(B, c, "Interference of waves", 2, "A mirror of a Michelson interferometer is moved by $0.100\\,\\mathrm{mm}$ while $500\\,\\mathrm{nm}$ light is used. How many bright fringes pass the field of view?", 2 * 0.100e-3 / (500 * NM), [0.100e-3 / (500 * NM), 4 * 0.100e-3 / (500 * NM), 0.100e-3 / (500 * NM) / 2, 8 * 0.100e-3 / (500 * NM)], "", ex("Moving the mirror by $\\Delta x$ changes the round-trip path by $2\\Delta x$, so $N=\\dfrac{2\\Delta x}{\\lambda}=\\dfrac{2(0.100\\times10^{-3})}{500\\times10^{-9}}=400$ fringes."), GEN(T35 + ", 35.4"), "gen", sig=3)
    mcq_num(B, c, "Interference of waves", 2, "At a point of a two-slit pattern the path difference is $\\lambda/4$. What fraction of the maximum intensity is observed there?", cos(45.0) ** 2, [cos(90.0) ** 2 + 0.25, 0.25, cos(45.0), 1.0], "", ex("Phase difference $\\phi=2\\pi\\dfrac{\\Delta}{\\lambda}=\\dfrac\\pi2$. $I=I_{\\max}\\cos^2\\dfrac\\phi2=I_{\\max}\\cos^245^\\circ=0.50\\,I_{\\max}$."), GEN(T35 + ", 35.17"), "gen", sig=2)
    y_m = 4 * 589 * NM * 1.2 / 0.25e-3
    mcq_num(B, c, "Young's double-slit experiment", 2, "Sodium light ($589\\,\\mathrm{nm}$) falls on two slits $0.25\\,\\mathrm{mm}$ apart. How far from the centre of a screen $1.2\\,\\mathrm{m}$ away is the fourth bright fringe ($m=4$)? (small angles)", y_m * 1e3, [y_m * 1e3 / 4, 3.5 * 589 * NM * 1.2 / 0.25e-3 * 1e3, y_m * 1e3 * 2, 589 * NM * 0.25e-3 / 1.2 * 1e3], "mm", ex("$y_m=\\dfrac{m\\lambda L}{d}=\\dfrac{4(589\\times10^{-9})(1.2)}{0.25\\times10^{-3}}=1.13\\times10^{-2}\\,\\mathrm{m}=11.3\\,\\mathrm{mm}$."), GEN(T35 + ", 35.6"), "gen", sig=3)
    mcq_pick(B, c, "Thin-film interference", 2, "A soap film held vertically becomes thinner at the top. In white light the very top, where the film is much thinner than a wavelength, appears", ["black (dark)", "white", "bright red", "bright blue"], 0, ex("At vanishing thickness the path difference is zero, but the front reflection (air to soap) has a half-wave phase change and the back one (soap to air) none: they cancel, so all colours are dark."), LEC10 + " (thin films)", "concept")
    mcq_pick(B, c, "Interference of waves", 2, "Constructive interference of two waves occurs when their path difference is", ["a whole number of wavelengths", "an odd number of half wavelengths", "a quarter wavelength", "zero only"], 0, ex("$\\Delta=m\\lambda$ ($m=0,\\pm1,\\dots$): crest meets crest. An odd number of half wavelengths gives destructive interference."), LEC10 + " (interference)", "concept")
    mcq_pick(B, c, "Interference of waves", 1, "The fringes in a two-slit experiment have equal brightness only if the two waves", ["have equal amplitudes and a fixed phase relationship", "have different frequencies", "come from different lasers", "are unpolarised and incoherent"], 0, ex("Equal amplitudes give complete cancellation at the minima; fixed phase (coherence) gives a stable pattern."), LEC10 + " (coherence)", "concept")
    mcq_pick(B, c, "Young's double-slit experiment", 2, "In a double-slit experiment with white light, the central fringe is", ["white, with coloured fringes on either side", "red", "dark", "violet"], 0, ex("At $\\theta=0$ the path difference is zero for every wavelength, so all colours interfere constructively: white. Elsewhere $y_m\\propto\\lambda$ separates the colours."), LEC10 + " (double-slit)", "concept")
    mcq_pick(B, c, "Young's double-slit experiment", 2, "If the slit separation $d$ in a double-slit experiment is doubled, the fringe spacing on the screen", ["is halved", "is doubled", "is unchanged", "is quadrupled"], 0, ex("$\\Delta y=\\dfrac{\\lambda L}{d}\\propto\\dfrac1d$."), LEC10 + " (double-slit)", "concept")

def ch11b(B):
    c = "c11"
    d, lam = 2.0e-6, 500 * NM
    mmax = int(d / lam - 1e-9)
    nlines = 2 * (mmax - 1) + 1 if abs(d / lam - mmax) < 1e-9 else 2 * mmax + 1
    mcq_num(B, c, "Diffraction gratings", 3, "A grating has a slit spacing of $2.0\\,\\mu\\mathrm{m}$. How many bright maxima (including the central one) can be seen on a screen when it is lit by $500\\,\\mathrm{nm}$ light at normal incidence?", nlines, [2 * 4 + 1, 4, 2 * 3, 3], "", ex("$\\sin\\theta_m=\\dfrac{m\\lambda}{d}=0.25\\,m\\le1$ gives $m\\le4$, but $m=4$ means $\\theta=90^\\circ$ (the beam grazes the grating and is not seen).", "Visible orders: $m=0,\\pm1,\\pm2,\\pm3$: $7$ maxima."), GEN(T36 + ", 36.26"), "gen", sig=2)
    N, m_, lam0 = 10000, 2, 600.0
    dl = lam0 / (N * m_)
    mcq_num(B, c, "Diffraction gratings", 3, "A grating with $10\\,000$ lines is used in second order near $600\\,\\mathrm{nm}$. What is the smallest wavelength difference it can resolve?", dl, [lam0 / N, lam0 / (N * m_ * m_), dl * 10, dl / 10], "nm", ex("Resolving power $R=\\dfrac{\\lambda}{\\Delta\\lambda}=Nm=(10\\,000)(2)=2\\times10^4$, so $\\Delta\\lambda=\\dfrac{600}{20\\,000}=0.030\\,\\mathrm{nm}$."), GEN(T36 + ", 36.33"), "gen", sig=2)
    d1 = 1 / 300.0 * 1e-3
    mx = int(d1 / (600 * NM))
    mcq_num(B, c, "Diffraction gratings", 3, "A grating has $300$ lines per millimetre and is lit by $600\\,\\mathrm{nm}$ light at normal incidence. What is the highest order that can be observed?", mx, [mx + 1, mx - 1, 2 * mx + 1, 3], "", ex("$d=\\dfrac{1}{300}\\,\\mathrm{mm}=3.33\\,\\mu\\mathrm{m}$ and $m_{\\max}<\\dfrac d\\lambda=5.56$: orders up to $m=5$ appear (and $m=6$ would need $\\sin\\theta>1$)."), GEN(T36 + ", 36.31"), "gen", sig=2)
    a_w = 10 * 550 * NM
    mcq_num(B, c, "Single-slit diffraction", 2, "A slit is ten wavelengths wide. At what angle is the first diffraction minimum?", asin(0.1), [asin(0.2), 10.0, asin(1.0), atan(10.0)], "deg", ex("$a\\sin\\theta=\\lambda\\Rightarrow\\sin\\theta=\\dfrac1{10}\\Rightarrow\\theta=5.74^\\circ$ (the slit width relative to the wavelength sets the spread)."), GEN(T36 + ", 36.1"), "gen", sig=3)
    lamC, dB = 0.154, 0.200
    thB = asin(lamC / (2 * dB))
    mcq_num(B, c, "X-ray diffraction", 2, "Copper $K\\alpha$ X-rays ($0.154\\,\\mathrm{nm}$) reflect from crystal planes $0.200\\,\\mathrm{nm}$ apart. At what glancing angle (from the planes) does the first-order Bragg maximum occur?", thB, [asin(lamC / dB), 90.0 - thB, atan(lamC / (2 * dB)), thB * 2], "deg", ex("$2d\\sin\\theta=m\\lambda$ with $m=1$: $\\sin\\theta=\\dfrac{0.154}{2(0.200)}=0.385\\Rightarrow\\theta=22.6^\\circ$."), GEN(T36 + ", 36.36"), "gen", sig=3)
    s_, a_hl, lam_h, D_p = 1.5, 0.005, 550 * NM, 0.005
    dmax = D_p * s_ / (1.22 * lam_h)
    mcq_num(B, c, "Circular apertures and resolution", 3, "The two headlights of a car are $1.5\\,\\mathrm{m}$ apart. At what greatest distance can an eye with a $5.0\\,\\mathrm{mm}$ pupil just resolve them (green light, $550\\,\\mathrm{nm}$)?", dmax, [dmax / 1000, dmax / 2, dmax * 2, 1.5 / (550 * NM) * 0.005 * 1.22], "m", ex("Rayleigh: $\\theta_{\\min}=1.22\\dfrac{\\lambda}{D}=1.22\\dfrac{550\\times10^{-9}}{5.0\\times10^{-3}}=1.34\\times10^{-4}\\,\\mathrm{rad}$; distance $=\\dfrac{s}{\\theta}=\\dfrac{1.5}{1.34\\times10^{-4}}=1.1\\times10^{4}\\,\\mathrm{m}$ ($11\\,\\mathrm{km}$, ignoring the atmosphere and the retina)."), GEN(T36 + ", 36.39"), "gen", sig=2)
    D_l, lam_l = 2.0e-3, 633 * NM
    thl = 1.22 * lam_l / D_l
    mcq_num(B, c, "Circular apertures and resolution", 3, "A He-Ne laser ($633\\,\\mathrm{nm}$) emits a beam through a $2.0\\,\\mathrm{mm}$ aperture. By diffraction alone, what is the diameter of the spot $100\\,\\mathrm{m}$ away (twice the distance to the first dark ring)?", 2 * 100.0 * thl, [100.0 * thl, 2 * 100.0 * lam_l / D_l, 2 * 100.0 * thl * 10, 2 * 100.0 * thl / 2], "m", ex("First dark ring at $\\theta=1.22\\dfrac\\lambda D=1.22\\dfrac{633\\times10^{-9}}{2.0\\times10^{-3}}=3.9\\times10^{-4}\\,\\mathrm{rad}$; spot diameter $=2L\\theta=2(100)(3.9\\times10^{-4})=7.7\\times10^{-2}\\,\\mathrm{m}$."), GEN(T36 + ", 36.37"), "gen", sig=2)
    b1 = 4.4934
    rel = (math.sin(b1) / b1) ** 2
    mcq_num(B, c, "Single-slit diffraction", 3, "In a single-slit pattern the first secondary maximum occurs near $\\beta=1.43\\pi=4.49\\,\\mathrm{rad}$. What fraction of the central intensity does it have?", rel, [1 / 4.4934, 0.5, math.sin(b1) ** 2, rel * 10], "", ex("$I/I_0=\\left(\\dfrac{\\sin\\beta}{\\beta}\\right)^2=\\left(\\dfrac{\\sin4.49}{4.49}\\right)^2=\\left(\\dfrac{-0.976}{4.49}\\right)^2=0.047$: the side maxima are only $4.7\\%$ as bright as the centre."), GEN(T36 + ", 36.14"), "gen", sig=2)
    mcq_pick(B, c, "Combined interference and diffraction", 3, "In a double-slit experiment the slit separation is twice the slit width ($d=2a$). Which interference orders are missing from the pattern?", ["the even orders $m=\\pm2,\\pm4,\\dots$", "the odd orders", "none", "only $m=\\pm1$"], 0, ex("An interference maximum $d\\sin\\theta=m\\lambda$ coincides with a single-slit minimum $a\\sin\\theta=p\\lambda$ when $m=p\\dfrac da=2p$: all even orders vanish."), LEC11 + " (double slit with finite width)", "concept")
    mcq_pick(B, c, "Circular apertures and resolution", 2, "Two stars appear as one blurred spot through a small telescope. Using a larger-diameter mirror (same wavelength) will", ["make it possible to resolve them", "make it harder to resolve them", "have no effect", "change only the brightness"], 0, ex("The smallest resolvable angle $1.22\\lambda/D$ decreases as the diameter $D$ increases."), LEC11 + " (resolution)", "concept")
    mcq_pick(B, c, "Single-slit diffraction", 2, "Diffraction of light by an obstacle is most noticeable when the size of the obstacle or opening is", ["comparable to the wavelength", "much larger than the wavelength", "much larger than the screen distance", "zero"], 0, ex("The spread $\\theta\\approx\\lambda/a$ is large only when $a$ is not much bigger than $\\lambda$; for $a\\gg\\lambda$ light travels in nearly straight lines (geometric optics)."), LEC11 + " (single slit)", "concept")
    mcq_pick(B, c, "X-ray diffraction", 1, "X-rays are used to study crystal structure because their wavelength is", ["comparable to the spacing between atoms in a crystal", "much longer than atomic spacings", "equal to that of visible light", "shorter than the nucleus"], 0, ex("Atomic planes are about $0.1\\,\\mathrm{nm}$ apart, the same size as X-ray wavelengths: the crystal acts as a 3-D diffraction grating (Bragg's law $2d\\sin\\theta=m\\lambda$)."), LEC11 + " (X-ray diffraction)", "concept")
    mcq_pick(B, c, "Diffraction gratings", 2, "Increasing the number of slits of a grating (same spacing) makes the principal maxima", ["narrower and brighter, in the same positions", "wider", "move outwards", "disappear"], 0, ex("Positions $d\\sin\\theta=m\\lambda$ depend only on $d$; the width shrinks as $1/N$ and the peak intensity grows as $N^2$."), LEC11 + " (gratings)", "concept")


def ch10c(B):
    c = "c10"
    mcq_num(B, c, "Thin-film interference", 2, "A soap bubble ($n=1.33$) in air looks bright blue ($450\\,\\mathrm{nm}$) in normal reflection. What is the smallest film thickness that can give this?", 450.0 / (4 * 1.33), [450.0 / (2 * 1.33), 450.0 / 4, 3 * 450.0 / (4 * 1.33), 450.0 / 1.33], "nm", ex("Air-soap-air: one half-wave phase change, so bright reflection needs $2nt=\\left(m+\\tfrac12\\right)\\lambda$. $t_{\\min}=\\dfrac{\\lambda}{4n}=\\dfrac{450}{4(1.33)}=84.6\\,\\mathrm{nm}$."), GEN(T35 + ", 35.26"), "gen", sig=3)
    th1 = asin(600 * NM / 0.10e-3)
    mcq_num(B, c, "Young's double-slit experiment", 2, "Two slits are $0.10\\,\\mathrm{mm}$ apart and illuminated by $600\\,\\mathrm{nm}$ light. At what angle is the first-order bright fringe?", th1, [asin(600 * NM / 0.10e-3 * 2), asin(600 * NM / 0.10e-3 / 2), th1 * 10, atan(0.10e-3 / (600 * NM))], "deg", ex("$d\\sin\\theta=\\lambda\\Rightarrow\\sin\\theta=\\dfrac{600\\times10^{-9}}{0.10\\times10^{-3}}=6.0\\times10^{-3}\\Rightarrow\\theta=0.34^\\circ$ (tiny: the small-angle approximation $\\theta\\approx\\lambda/d=6\\times10^{-3}\\,\\mathrm{rad}$ is excellent)."), GEN(T35 + ", 35.19"), "gen", sig=2)
    mcq_pick(B, c, "Interference of waves", 1, "Two coherent waves arrive at a point with a path difference of $2.5\\,\\lambda$. The interference there is", ["destructive", "constructive", "partly constructive", "impossible to tell"], 0, ex("$\\Delta=2.5\\lambda=\\left(2+\\tfrac12\\right)\\lambda$: a half-integer number of wavelengths, so the waves are in antiphase and cancel."), GEN(T35 + ", 35.2"), "gen")
    mcq_pick(B, c, "Young's double-slit experiment", 2, "In a double-slit experiment the two slits are fed with waves that are $180^\\circ$ out of phase. Compared with in-phase sources, the central fringe on the axis is", ["dark instead of bright", "unchanged", "twice as bright", "wider"], 0, ex("On the axis the path difference is zero, but the sources are in antiphase, so the waves cancel: the whole pattern shifts by half a fringe (bright and dark fringes exchange)."), LEC10 + " (double-slit)", "concept")
    lam_ = 3.0e-3 * 0.20e-3 / 2.0
    mcq_num(B, c, "Young's double-slit experiment", 2, "Fringes $6.0\\,\\mathrm{mm}$ apart are seen on a screen $2.0\\,\\mathrm{m}$ from two slits $0.20\\,\\mathrm{mm}$ apart. What is the wavelength of the light?", 6.0e-3 * 0.20e-3 / 2.0 / NM, [6.0e-3 * 2.0 / 0.20e-3 / NM, 6.0e-3 * 0.20e-3 * 2.0 / NM, 6.0e-3 * 0.20e-3 / 2.0 / NM * 2, 6.0e-3 * 0.20e-3 / 2.0 / NM / 2], "nm", ex("$\\Delta y=\\dfrac{\\lambda L}{d}\\Rightarrow\\lambda=\\dfrac{\\Delta y\\,d}{L}=\\dfrac{(6.0\\times10^{-3})(0.20\\times10^{-3})}{2.0}=6.0\\times10^{-7}\\,\\mathrm{m}=600\\,\\mathrm{nm}$ (orange)."), GEN(T35 + ", 35.6"), "gen", sig=2)
    mcq_num(B, c, "Young's double-slit experiment", 2, "Two slits $0.050\\,\\mathrm{mm}$ apart are lit by $500\\,\\mathrm{nm}$ light. What is the angular spacing between adjacent bright fringes (small angles)?", 500 * NM / 0.050e-3, [500 * NM / 0.050e-3 * 2, 500 * NM * 0.050e-3, 0.050e-3 / (500 * NM), 500 * NM / 0.050e-3 / 2], "rad", ex("$\\Delta\\theta\\approx\\dfrac{\\lambda}{d}=\\dfrac{500\\times10^{-9}}{0.050\\times10^{-3}}=1.0\\times10^{-2}\\,\\mathrm{rad}$ ($0.57^\\circ$)."), GEN(T35 + ", 35.19"), "gen", sig=2)
